#[test]
fn deferred_materialization_binds_nested_component_without_replacing_repository_root() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let repository = tempfile::tempdir().expect("materialized repository");
        homeboy_core::test_support::run_git_fixture_command(repository.path(), &["init", "-q"]);
        let component_path = repository.path().join("packages/php-transformer");
        std::fs::create_dir_all(&component_path).expect("nested component");
        let registrations = home.path().join(".config/homeboy/components");
        std::fs::create_dir_all(&registrations).expect("component registrations");
        std::fs::write(
            registrations.join("php-transformer.json"),
            serde_json::json!({
                "local_path": component_path,
                "remote_url": "https://github.com/example/blocks-engine.git"
            })
            .to_string(),
        )
        .expect("register nested component");

        let attached_checkout = tempfile::tempdir().expect("project attachment checkout");
        std::fs::write(
            attached_checkout.path().join("homeboy.json"),
            serde_json::json!({
                "id": "php-transformer",
                "remote_url": "https://github.com/example/attached-project.git"
            })
            .to_string(),
        )
        .expect("portable project attachment identity");
        homeboy_core::project::save(&homeboy_core::project::Project {
            id: "attached-site".to_string(),
            components: vec![homeboy_core::project::ProjectComponentAttachment {
                id: "php-transformer".to_string(),
                local_path: attached_checkout.path().display().to_string(),
                ..Default::default()
            }],
            ..Default::default()
        })
        .expect("register same-id project attachment");
        assert_eq!(
            homeboy_core::component::registered_by_id("php-transformer")
                .expect("project-scoped lookup")
                .expect("attachment")
                .local_path,
            attached_checkout.path().display().to_string(),
        );

        let mut plan = AgentTaskPlan::new(
            "deferred-component",
            vec![AgentTaskRequest {
                schema: crate::agent_task::AGENT_TASK_REQUEST_SCHEMA.to_string(),
                task_id: "task-a".to_string(),
                group_key: Some("blocks-engine".to_string()),
                parent_plan_id: None,
                executor: AgentTaskExecutor {
                    backend: "fixture".to_string(),
                    selector: None,
                    runtime_selection: None,
                    required_capabilities: Vec::new(),
                    secret_env: Vec::new(),
                    model: None,
                    config: Value::Null,
                },
                instructions: "run".to_string(),
                inputs: Value::Null,
                source_refs: Vec::new(),
                workspace: AgentTaskWorkspace::default(),
                component_contracts: Vec::new(),
                policy: AgentTaskPolicy::default(),
                limits: AgentTaskLimits::default(),
                expected_artifacts: Vec::new(),
                artifact_declarations: Vec::new(),
                output_declarations: Vec::new(),
                runtime_tools: Vec::new(),
                metadata: Value::Null,
            }],
        );
        plan.group_key = Some("blocks-engine".to_string());
        bind_materialized_cook_component_workspace(
            &mut plan,
            repository.path(),
            Some("php-transformer"),
        )
        .expect("bind deferred component workspace");

        assert!(plan.tasks[0].workspace.root.is_none());
        assert_eq!(
            plan.tasks[0].executor.config["component_cwd"],
            "packages/php-transformer"
        );
        assert_eq!(
            plan.metadata["gate_workspace"]["component_cwd"],
            "packages/php-transformer"
        );
        assert_eq!(
            plan.metadata["gate_workspace"]["requested_cwd"],
            repository.path().display().to_string()
        );

        #[cfg(unix)]
        {
            let alias_parent = tempfile::tempdir().expect("alias parent");
            let alias = alias_parent.path().join("checkout");
            std::os::unix::fs::symlink(repository.path(), &alias).expect("repository alias");
            let mut aliased = plan.clone();
            bind_materialized_cook_component_workspace(
                &mut aliased,
                &alias,
                Some("php-transformer"),
            )
            .expect("canonical containment accepts a repository-root alias");
            assert_eq!(
                aliased.metadata["gate_workspace"]["requested_cwd"],
                alias.display().to_string()
            );
            assert_eq!(
                aliased.metadata["gate_workspace"]["component_cwd"],
                "packages/php-transformer"
            );

            let outside = tempfile::tempdir().expect("outside workspace");
            std::os::unix::fs::symlink(outside.path(), repository.path().join("escaped-component"))
                .expect("escaping component alias");
            let mut escaped = plan.clone();
            escaped.metadata["cook_repository_identity"] = serde_json::json!({
                "component_cwd": "escaped-component"
            });
            let before = serde_json::to_value(&escaped).expect("plan snapshot");
            assert!(bind_materialized_cook_component_workspace(
                &mut escaped,
                repository.path(),
                Some("php-transformer")
            )
            .is_err());
            assert_eq!(
                serde_json::to_value(&escaped).expect("unchanged plan"),
                before
            );
        }

        let mut stale = plan.clone();
        stale.metadata["cook_repository_identity"] = serde_json::json!({
            "repository_name": "blocks-engine",
            "component_id": "removed-transformer",
            "component_registered": true,
            "provenance": "--repo:configured-component"
        });
        let error = bind_materialized_cook_component_workspace(&mut stale, repository.path(), None)
            .expect_err("stale component registration must fail closed");
        assert!(error.message.contains("no longer registered"));

        let mut unattested = plan.clone();
        unattested.metadata["cook_repository_identity"] = serde_json::json!({
            "repository_name": "standalone-repository",
            "component_id": "removed-transformer"
        });
        bind_materialized_cook_component_workspace(&mut unattested, repository.path(), None)
            .expect("a component label without registration evidence grants no binding authority");

        let mut unregistered = plan.clone();
        unregistered.metadata["cook_repository_identity"] = serde_json::json!({
            "repository_name": "standalone-repository",
            "component_id": "standalone-repository",
            "component_registered": false,
            "provenance": "--cwd:git-remote:origin"
        });
        bind_materialized_cook_component_workspace(&mut unregistered, repository.path(), None)
            .expect("an attested standalone repository uses its root workspace");
    });
}

static CONFIG_LOCK_STRICT_TEST: LazyLock<Mutex<()>> = LazyLock::new(|| Mutex::new(()));

fn with_strict_config_lock(test: impl FnOnce()) {
    let _guard = CONFIG_LOCK_STRICT_TEST
        .lock()
        .expect("strict lock test guard");
    std::env::set_var(homeboy_core::config::CONFIG_LOCK_STRICT_ENV, "1");
    struct StrictLockEnv;
    impl Drop for StrictLockEnv {
        fn drop(&mut self) {
            std::env::remove_var(homeboy_core::config::CONFIG_LOCK_STRICT_ENV);
        }
    }
    let _env = StrictLockEnv;
    test();
}

/// `agent_task_lifecycle::submit_plan` against an explicitly injected store.
///
/// The ambient wrapper resolves its store from the process environment and
/// admits through `paths::controller_runtimes_store()`, which stays
/// process-global by design. A hermetic test must not enqueue against the
/// operator's real admission queue, so runtime admission is supplied as stub
/// evidence exactly as the rooted proofs in `agent_task_lifecycle::tests` do.
/// Only the store and that admission edge change; the plan and the requested
/// run identity are passed through untouched (#7505).
fn submit_plan_in_test_store(
    lifecycle_store: &AgentTaskLifecycleStore,
    plan: &AgentTaskPlan,
    requested_run_id: Option<&str>,
) -> Result<agent_task_lifecycle::AgentTaskRunRecord> {
    agent_task_lifecycle::submit_plan_with_runtime_admission_in_store(
        lifecycle_store,
        plan,
        requested_run_id,
        None,
        None,
        None,
        |_| Ok(serde_json::json!({})),
    )
}

#[test]
fn deepest_typed_error_selects_the_deepest_explicit_cause() {
    let diagnostic = serde_json::json!({
        "cause": {
            "schema": "homeboy/command-result/v3",
            "success": false,
            "error": {
                "code": "promotion.rejected",
                "message": "promotion rejected",
                "details": {
                    "cause": {
                        "schema": "homeboy/command-result/v3",
                        "success": false,
                        "error": {
                            "code": "gate.failed",
                            "message": "gate failed",
                            "details": { "field": "verify" }
                        }
                    }
                }
            }
        }
    });

    assert_eq!(
        deepest_typed_error(&diagnostic),
        Some(serde_json::json!({
            "code": "gate.failed",
            "field": "verify",
            "message": "gate failed"
        }))
    );
}

#[test]
fn deepest_typed_error_ignores_sibling_envelopes_and_json_strings() {
    let primary = serde_json::json!({
        "schema": "homeboy/command-result/v3",
        "success": false,
        "error": { "code": "promotion.rejected", "message": "promotion rejected" }
    });
    let unrelated_sibling = serde_json::json!({
        "schema": "homeboy/command-result/v3",
        "success": false,
        "error": { "code": "unrelated", "message": "unrelated sibling" }
    });
    assert_eq!(
        deepest_typed_error(&serde_json::json!({
            "cause": primary,
            "provider_response": unrelated_sibling,
        })),
        Some(serde_json::json!({
            "code": "promotion.rejected",
            "field": null,
            "message": "promotion rejected"
        }))
    );
    assert!(deepest_typed_error(&serde_json::json!({
        "cause": r#"{"schema":"homeboy/command-result/v3","success":false,"error":{"code":"untrusted","message":"provider transcript"}}"#
    }))
    .is_none());
}

