#[test]
fn remediation_policy_rejects_denied_workspace_read_before_dispatch() {
    let mut request = AgentTaskRequest {
        schema: crate::agent_task::AGENT_TASK_REQUEST_SCHEMA.to_string(),
        task_id: "gate-fix".to_string(),
        group_key: None,
        parent_plan_id: None,
        executor: AgentTaskExecutor {
            backend: "fixture".to_string(),
            selector: None,
            runtime_selection: None,
            required_capabilities: Vec::new(),
            secret_env: Vec::new(),
            model: None,
            config: Value::Null,
        },
        instructions: "Fix the failing gate.".to_string(),
        inputs: Value::Null,
        source_refs: Vec::new(),
        workspace: AgentTaskWorkspace::default(),
        component_contracts: Vec::new(),
        policy: AgentTaskPolicy::default(),
        limits: AgentTaskLimits::default(),
        expected_artifacts: Vec::new(),
        artifact_declarations: Vec::new(),
        output_declarations: Vec::new(),
        runtime_tools: Vec::new(),
        metadata: Value::Null,
    };

    assert_eq!(
        remediation_tool_policy_error(&request).as_deref(),
        Some(
            "Cook remediation policy must grant the runner read access to the task workspace before dispatch"
        )
    );

    request.policy.grant_workspace_read_tool();
    assert!(remediation_tool_policy_error(&request).is_none());
}

#[test]
fn terminal_review_form_continuation_rejects_generic_failed_and_cancelled_runs() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let options = batch_cook_options(
            "generic-terminal-review-form",
            Arc::new(AcceptedDetachedAttemptDispatcher),
        );
        for (run_id, cancelled) in [
            ("generic-terminal-review-form-failed", false),
            ("generic-terminal-review-form-cancelled", true),
        ] {
            agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id))
                .unwrap();
            if cancelled {
                agent_task_lifecycle::cancel_run(run_id, Some("policy cancelled")).unwrap();
            } else {
                agent_task_lifecycle::record_pre_execution_failure(
                    run_id,
                    &options.identity.initial_plan,
                    "fixture",
                    &Error::validation_invalid_argument(
                        "fixture",
                        "generic policy failure",
                        None,
                        None,
                    ),
                )
                .unwrap();
            }
            let record = agent_task_lifecycle::reconcile_status(run_id).unwrap();
            assert!(!terminal_review_form_continuation_is_eligible(
                &options.identity.initial_plan,
                &record,
            )
            .unwrap());
        }
    });
}

#[test]
fn run_next_skips_persisted_test_detached_recipe_and_executes_eligible_work() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let options = batch_cook_options(
            "run-next-ineligible-test-detached",
            Arc::new(AcceptedDetachedAttemptDispatcher),
        );
        persist_initial_recipe(&options).expect("persisted test-detached recipe");
        agent_task_lifecycle::submit_plan(
            &options.identity.initial_plan,
            Some(&options.identity.initial_run_id),
        )
        .expect("declared Cook attempt submitted");
        agent_task_lifecycle::rewrite_record_for_test(&options.identity.initial_run_id, |record| {
            record.submitted_at = "2000-01-01T00:00:00+00:00".to_string();
        })
        .expect("deterministic durable submission timestamp");
        agent_task_lifecycle::cancel_run(
            &options.identity.initial_run_id,
            Some("fixture terminal"),
        )
        .expect("declared Cook attempt terminal");
        super::super::enqueue_terminal_continuation(
            &options.identity.cook_id,
            &options.identity.initial_run_id,
        )
        .expect("durable Cook continuation queued");

        agent_task_lifecycle::submit_plan(
            &batch_cook_options(
                "run-next-eligible-work",
                Arc::new(AcceptedDetachedAttemptDispatcher),
            )
            .identity
            .initial_plan,
            Some("run-next-eligible-work"),
        )
        .expect("eligible work queued");

        let result = super::super::run_next_with_cook_dispatcher(
            Arc::new(ImmediateSuccessExecutor),
            |_| Ok(None),
            None,
        )
        .expect("ineligible continuation does not block eligible work");

        assert_eq!(
            result.value.expect("eligible aggregate").plan_id,
            "run-next-eligible-work"
        );
        assert_eq!(result.skipped.len(), 1);
        assert_eq!(result.skipped[0].run_id, options.identity.initial_run_id);
        assert_eq!(
            result.skipped[0].submitted_at.as_deref(),
            Some("2000-01-01T00:00:00+00:00")
        );
        assert!(result.skipped[0]
            .age_seconds
            .is_some_and(|age_seconds| age_seconds > 800_000_000));
        assert_eq!(
            result.skipped[0].dispatcher_kind.as_deref(),
            Some("test-detached")
        );
        assert_eq!(
            result.skipped[0].category,
            "cook_continuation_preflight_failed"
        );
        assert_eq!(result.skipped[0].error_code, "validation.invalid_argument");
        assert_eq!(
            result.skipped[0].remediation,
            format!(
                "inspect retained diagnostics with: homeboy agent-task diagnose {} --full",
                options.identity.initial_run_id
            )
        );
    });
}

#[test]
fn run_next_redacts_poisoned_recipe_dispatcher_kind() {
    homeboy_core::test_support::with_isolated_home(|_| {
        const POISONED_KIND: &str = "LEAK_RECIPE_DISPATCHER_SECRET";
        let options = batch_cook_options(
            "run-next-poisoned-recipe",
            Arc::new(AcceptedDetachedAttemptDispatcher),
        );
        persist_initial_recipe(&options).expect("persisted recipe");
        agent_task_lifecycle::submit_plan(
            &options.identity.initial_plan,
            Some(&options.identity.initial_run_id),
        )
        .expect("declared Cook attempt submitted");
        agent_task_lifecycle::cancel_run(
            &options.identity.initial_run_id,
            Some("fixture terminal"),
        )
        .expect("declared Cook attempt terminal");
        super::super::enqueue_terminal_continuation(
            &options.identity.cook_id,
            &options.identity.initial_run_id,
        )
        .expect("durable Cook continuation queued");

        let recipe_path = homeboy_core::paths::homeboy_data()
            .expect("data path")
            .join("agent-task-cooks")
            .join(&options.identity.cook_id)
            .join("recipe.json");
        let mut recipe: Value =
            serde_json::from_slice(&std::fs::read(&recipe_path).expect("persisted recipe bytes"))
                .expect("persisted recipe JSON");
        recipe["promotion_transport"]["attempt_dispatch"]["kind"] =
            serde_json::json!(POISONED_KIND);
        std::fs::write(
            &recipe_path,
            serde_json::to_vec(&recipe).expect("poisoned recipe JSON"),
        )
        .expect("poisoned recipe persisted");

        agent_task_lifecycle::submit_plan(
            &batch_cook_options(
                "run-next-after-poisoned-recipe",
                Arc::new(AcceptedDetachedAttemptDispatcher),
            )
            .identity
            .initial_plan,
            Some("run-next-after-poisoned-recipe"),
        )
        .expect("eligible work queued");

        let result = super::super::run_next_with_cook_dispatcher(
            Arc::new(ImmediateSuccessExecutor),
            |_| Ok(None),
            None,
        )
        .expect("poisoned continuation does not block eligible work");
        let status = agent_task_lifecycle::reconcile_status(&options.identity.initial_run_id)
            .expect("continuation record status");
        let logs = agent_task_lifecycle::logs(&options.identity.initial_run_id)
            .expect("continuation record logs");
        let rendered = serde_json::to_string(&serde_json::json!({
            "queue_skips": result.skipped,
            "status": status,
            "logs": logs,
        }))
        .expect("queue projections serialize");

        assert_eq!(
            result.value.expect("eligible aggregate").plan_id,
            "run-next-after-poisoned-recipe"
        );
        assert!(!rendered.contains(POISONED_KIND));
        assert!(rendered.contains("cook_continuation_unsupported_dispatcher"));
        assert!(rendered.contains(&format!(
            "agent-task diagnose {} --full",
            options.identity.initial_run_id
        )));
    });
}

#[test]
fn durable_cook_inspection_reports_an_unsupported_run_schema() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let options = batch_cook_options(
            "unsupported-durable-cook-schema",
            Arc::new(AcceptedDetachedAttemptDispatcher),
        );
        let run_id = "unsupported-durable-cook-schema-attempt-1";
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id)).unwrap();
        agent_task_lifecycle::inject_raw_record_metadata_for_corruption_test(run_id, |metadata| {
            metadata["agent_task_run"]["schema"] = serde_json::json!("homeboy/agent-task-run/v999");
        })
        .unwrap();

        let error = agent_task_lifecycle::reconcile_status(run_id)
            .expect_err("unsupported durable record schema must be diagnosable");
        assert!(error
            .message
            .contains("unsupported durable agent-task run schema"));
        assert!(error.message.contains("homeboy/agent-task-run/v999"));
    });
}

fn seed_review_form_aggregate(run_id: &str, plan: &AgentTaskPlan) {
    let aggregate = review_form_aggregate(plan);
    agent_task_lifecycle::record_run_aggregate(run_id, plan, &aggregate).unwrap();
}

fn review_form_aggregate(plan: &AgentTaskPlan) -> crate::agent_task_scheduler::AgentTaskAggregate {
    use crate::agent_task::{AgentTaskOutcome, AgentTaskOutcomeStatus};
    use crate::agent_task_scheduler::{
        AgentTaskAggregate, AgentTaskAggregateStatus, AgentTaskAggregateTotals,
    };
    let form = test_review_form();
    let task = plan.tasks.first().expect("review form plan has one task");
    AgentTaskAggregate {
        schema: crate::agent_task::AGENT_TASK_AGGREGATE_SCHEMA.to_string(),
        plan_id: plan.plan_id.clone(),
        status: AgentTaskAggregateStatus::Succeeded,
        totals: AgentTaskAggregateTotals {
            succeeded: 1,
            ..Default::default()
        },
        outcomes: vec![AgentTaskOutcome {
            task_id: task.task_id.clone(),
            status: AgentTaskOutcomeStatus::Succeeded,
            summary: Some("provider dispatched once".to_string()),
            outputs: serde_json::json!({ "review_form": form }),
            metadata: serde_json::json!({ "model": task.executor.model() }),
            ..Default::default()
        }],
        events: Vec::new(),
        artifact_lineage: Vec::new(),
        child_runs: Vec::new(),
        artifact_bindings: Vec::new(),
        queue: Default::default(),
    }
}

fn seed_timeout_review_form_aggregate(run_id: &str, plan: &AgentTaskPlan) {
    use crate::agent_task::{AgentTaskOutcome, AgentTaskOutcomeStatus};
    use crate::agent_task_scheduler::{
        AgentTaskAggregate, AgentTaskAggregateStatus, AgentTaskAggregateTotals,
    };

    let task = plan.tasks.first().expect("review form plan has one task");
    agent_task_lifecycle::record_run_aggregate(
        run_id,
        plan,
        &AgentTaskAggregate {
            schema: crate::agent_task::AGENT_TASK_AGGREGATE_SCHEMA.to_string(),
            plan_id: plan.plan_id.clone(),
            status: AgentTaskAggregateStatus::Failed,
            totals: AgentTaskAggregateTotals {
                failed: 1,
                ..Default::default()
            },
            outcomes: vec![AgentTaskOutcome {
                task_id: task.task_id.clone(),
                status: AgentTaskOutcomeStatus::Timeout,
                summary: Some("review form provider timed out".to_string()),
                metadata: serde_json::json!({ "model": task.executor.model() }),
                ..Default::default()
            }],
            events: Vec::new(),
            artifact_lineage: Vec::new(),
            child_runs: Vec::new(),
            artifact_bindings: Vec::new(),
            queue: Default::default(),
        },
    )
    .unwrap();
}

#[test]
fn provider_timeout_report_surfaces_budget_and_exact_recovery() {
    let context = homeboy_core::test_support::HermeticTestContext::new();
    let lifecycle_store = AgentTaskLifecycleStore::new(context.path_roots());
    let recipe_store = CookRecipeStore::new(context.path_roots());
    let options = compile_options("timeout-report");
    recipe_store
        .persist_initial_recipe(&options)
        .expect("persist timeout recipe");
    let mut plan = options.identity.initial_plan.clone();
    plan.options.timeout_ms = Some(1_200_000);
    plan.tasks[0].limits.timeout_ms = Some(1_200_000);
    lifecycle_store
        .submit_plan_with_runtime_admission(&plan, "timeout-run", |_| Ok(serde_json::json!({})))
        .expect("persist timeout run");
    lifecycle_store
        .record_cook_attempt("timeout-report", 1, "timeout-run")
        .expect("index timeout run");
    lifecycle_store
        .mutate_record("timeout-run", |record| {
            let identity = homeboy_lab_contract::ExecutionPlacementIdentity {
                repository: "fixture".to_string(),
                workspace: "fixture".to_string(),
                task: "task".to_string(),
                candidate: None,
                base: None,
            };
            record.metadata["execution_placement_decision"] = serde_json::to_value(
                homeboy_lab_contract::ExecutionPlacementDecision::controller_local(
                    "fixture",
                    "v1",
                    identity,
                    homeboy_lab_contract::Placement::Local,
                ),
            )
            .unwrap();
            true
        })
        .expect("persist rooted placement");
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.status = crate::agent_task_scheduler::AgentTaskAggregateStatus::Failed;
    aggregate.outcomes[0].status = crate::agent_task::AgentTaskOutcomeStatus::Timeout;
    aggregate.outcomes[0].failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::Timeout);
    aggregate.outcomes[0].diagnostics = vec![crate::agent_task::AgentTaskDiagnostic {
        class: "agent_task.provider_timeout".to_string(),
        message: "provider exceeded timeout_ms=1200000".to_string(),
        data: serde_json::json!({ "timeout_ms": 1_200_000 }),
    }];
    let mut report = AgentTaskRunResult {
        value: AgentTaskCookReport {
            schema: "homeboy/agent-task-cook/v1",
            cook_id: "timeout-report".to_string(),
            latest_run_id: Some("timeout-run".to_string()),
            history_run_ids: vec!["timeout-run".to_string()],
            invocation_run_ids: vec!["timeout-run".to_string()],
            status: "provider_failure".to_string(),
            disposition: CookDisposition::Terminal,
            attempts: Vec::new(),
            finalization: None,
            intentional_no_change: None,
            selected_candidate: None,
            stop_reason: None,
            terminal_phase: None,
            terminal_failure_classification: None,
            primary_failure: None,
            provider_route_notes: Vec::new(),
            failure_context: Some(AgentTaskCookFailureContext {
                recovery_step: None,
                cook_id: "timeout-report".to_string(),
                latest_run_id: "timeout-run".to_string(),
                selected_run_id: None,
                selected_task_id: None,
                selected_candidate_sha: None,
                promotion_provenance: None,
                durable_recipe_ref: "homeboy://agent-task/cooks/timeout-report/recipe".to_string(),
                lifecycle_state: "Failed".to_string(),
                phase: "provider".to_string(),
                reason_code: "failed".to_string(),
                diagnostic: None,
                continuation_admission: None,
                blocking_claim: None,
                provider_budget_consumed: true,
                provider_executions_consumed: 1,
                recovery_legal: false,
                recovery_reason: "generic".to_string(),
                legal_actions: Vec::new(),
                next_actions: Vec::new(),
            }),
            report_stores: None,
        },
        exit_code: 1,
    };

    make_provider_timeout_actionable(
        Some(&lifecycle_store),
        &mut report,
        &aggregate,
        &plan,
        "timeout-run",
        Some(AgentTaskExecutionBudget::new(1, 1, 0)),
        false,
    );

    assert_eq!(
        report.value.terminal_failure_classification.as_deref(),
        Some("provider_timeout")
    );
    assert_eq!(report.value.terminal_phase.as_deref(), Some("provider"));
    assert!(report.value.finalization.is_none());
    let stop_reason = report.value.stop_reason.as_deref().expect("stop reason");
    assert!(stop_reason.contains("timeout_ms=1200000"));
    assert!(stop_reason.contains("finalization were not reached"));
    let context = report.value.failure_context.expect("failure context");
    assert_eq!(context.reason_code, "provider_timeout");
    assert_eq!(
        context.diagnostic.as_ref().unwrap()["data"]["remaining_provider_executions"],
        1
    );
    assert_eq!(
        context.legal_actions[0].command,
        "homeboy --placement local agent-task recover timeout-run --timeout-ms 2400000"
    );

    report.value.failure_context = Some(context);
    bind_report_to_stores(&mut report.value, &recipe_store, &lifecycle_store, true);
    let rebound = report
        .value
        .failure_context
        .expect("rebound failure context");
    assert_eq!(rebound.reason_code, "provider_timeout");
    assert_eq!(
        rebound.diagnostic.expect("timeout diagnostic")["class"],
        "agent_task.provider_timeout"
    );
    assert_eq!(
        rebound.legal_actions[0].command,
        "homeboy --placement local agent-task recover timeout-run --timeout-ms 2400000"
    );
}

/// Regression for #14732: the terminal failure previously advertised a
/// `recover --timeout-ms` resume command in `next_actions` even while
/// `recovery_legal` was false because deferred cleanup had not gone terminal.
/// An operator following the printed guidance hit a durable retry that the
/// run's own admission had already refused. Only a command that is admitted
/// right now may appear in `next_actions`.
#[test]
fn provider_timeout_resume_is_not_offered_while_deferred_cleanup_is_pending() {
    let context = homeboy_core::test_support::HermeticTestContext::new();
    let lifecycle_store = AgentTaskLifecycleStore::new(context.path_roots());
    let recipe_store = CookRecipeStore::new(context.path_roots());
    let options = compile_options("timeout-pending-cleanup");
    recipe_store
        .persist_initial_recipe(&options)
        .expect("persist timeout recipe");
    let mut plan = options.identity.initial_plan.clone();
    plan.options.timeout_ms = Some(1_200_000);
    plan.tasks[0].limits.timeout_ms = Some(1_200_000);
    lifecycle_store
        .submit_plan_with_runtime_admission(&plan, "timeout-pending-run", |_| {
            Ok(serde_json::json!({}))
        })
        .expect("persist timeout run");
    lifecycle_store
        .record_cook_attempt("timeout-pending-cleanup", 1, "timeout-pending-run")
        .expect("index timeout run");

    let mut aggregate = review_form_aggregate(&plan);
    aggregate.status = crate::agent_task_scheduler::AgentTaskAggregateStatus::Failed;
    aggregate.outcomes[0].status = crate::agent_task::AgentTaskOutcomeStatus::Timeout;
    aggregate.outcomes[0].failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::Timeout);
    aggregate.outcomes[0].diagnostics = vec![crate::agent_task::AgentTaskDiagnostic {
        class: "agent_task.provider_timeout".to_string(),
        message: "provider exceeded timeout_ms=1200000".to_string(),
        data: serde_json::json!({ "timeout_ms": 1_200_000 }),
    }];

    let mut report = cook_report(CookReportInput {
        cook_id: "timeout-pending-cleanup".to_string(),
        status: "provider_failure",
        disposition: CookDisposition::Terminal,
        attempts: Vec::new(),
        finalization: None,
        stop_reason: None,
        exit_code: 1,
        invocation_latest_run_id: Some("timeout-pending-run"),
    });
    report.value.failure_context = Some(AgentTaskCookFailureContext {
        recovery_step: None,
        cook_id: "timeout-pending-cleanup".to_string(),
        latest_run_id: "timeout-pending-run".to_string(),
        selected_run_id: None,
        selected_task_id: None,
        selected_candidate_sha: None,
        promotion_provenance: None,
        durable_recipe_ref: "homeboy://agent-task/cooks/timeout-pending-cleanup/recipe".to_string(),
        lifecycle_state: "Failed".to_string(),
        phase: "provider".to_string(),
        reason_code: "failed".to_string(),
        diagnostic: None,
        continuation_admission: None,
        blocking_claim: None,
        provider_budget_consumed: true,
        provider_executions_consumed: 1,
        recovery_legal: false,
        recovery_reason: "generic".to_string(),
        legal_actions: Vec::new(),
        next_actions: Vec::new(),
    });

    // `provider_execution_active: true` is the same "deferred cleanup has not
    // gone terminal yet" signal the real timeout path observes when a
    // provider process is still winding down.
    make_provider_timeout_actionable(
        Some(&lifecycle_store),
        &mut report,
        &aggregate,
        &plan,
        "timeout-pending-run",
        Some(AgentTaskExecutionBudget::new(1, 1, 0)),
        true,
    );

    let context = report.value.failure_context.expect("failure context");
    assert!(
        !context.recovery_legal,
        "recovery must not be legal while cleanup is pending"
    );
    assert!(
        context.recovery_reason.contains("deferred cleanup"),
        "{}",
        context.recovery_reason
    );
    assert!(
        context.legal_actions.is_empty(),
        "no legal actions while cleanup is pending: {:?}",
        context.legal_actions
    );
    assert!(
        context.next_actions.iter().all(|action| {
            action.action.as_str() != "resume" && !action.command.contains("agent-task recover")
        }),
        "next_actions must not offer a resume command while cleanup is pending: {:?}",
        context.next_actions
    );
    assert!(
        context
            .next_actions
            .iter()
            .any(|action| action.command.contains("diagnose")),
        "the diagnose action remains offered: {:?}",
        context.next_actions
    );
}

#[test]
fn unfingerprinted_timeout_next_action_is_worktree_git_status_not_retry() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let workspace = tempfile::tempdir().expect("workspace");
        let mut options = compile_options("timeout-unfingerprinted");
        options.identity.initial_plan.tasks[0].workspace.root =
            Some(workspace.path().display().to_string());
        persist_initial_recipe(&options).expect("persist recipe");
        agent_task_lifecycle::submit_plan(
            &options.identity.initial_plan,
            Some(&options.identity.initial_run_id),
        )
        .expect("submit");
        let _ = agent_task_lifecycle::record_cook_attempt_in_store(
            &test_lifecycle_store(),
            &options.identity.cook_id,
            1,
            &options.identity.initial_run_id,
        );
        agent_task_lifecycle::record_cook_controller_failure_in_store(
            &test_lifecycle_store(),
            &options.identity.initial_run_id,
            &serde_json::json!({
                "code": "validation.invalid_argument",
                "message": "recoverable-candidate promotion requires a fingerprinted artifact bound to its producing run, task, base, and workspace",
            }),
        )
        .expect("record fingerprint failure");

        let context = super::super::cook_failure_context(
            &options.identity.cook_id,
            Some(&options.identity.initial_run_id),
            "durable_failure",
        )
        .expect("failure context");

        assert_eq!(
            context.next_actions[0].command,
            format!(
                "git -C {} status",
                quote_arg(workspace.path().to_str().expect("utf8"))
            )
        );
        assert!(context
            .next_actions
            .iter()
            .chain(&context.legal_actions)
            .all(|action| {
                !action.command.contains("retry") && !action.command.contains("agent-task recover")
            }));
    });
}

#[test]
fn startup_without_output_liveness_is_projected_without_becoming_a_timeout() {
    let plan = compile_options("startup-without-output-report")
        .identity
        .initial_plan;
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.status = crate::agent_task_scheduler::AgentTaskAggregateStatus::Failed;
    aggregate.outcomes[0].status = crate::agent_task::AgentTaskOutcomeStatus::Timeout;
    aggregate.outcomes[0].failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::Timeout);
    aggregate.outcomes[0].diagnostics = vec![
        crate::agent_task::AgentTaskDiagnostic {
            class: "agent_task.provider_timeout".to_string(),
            message: "provider exceeded timeout_ms=1200000".to_string(),
            data: serde_json::json!({ "timeout_ms": 1_200_000 }),
        },
        crate::agent_task::AgentTaskDiagnostic {
            class: "agent_task.provider_rotation_exhausted".to_string(),
            message: "an earlier provider rotation exhausted".to_string(),
            data: serde_json::json!({}),
        },
    ];
    let mut startup_outcome = aggregate.outcomes[0].clone();
    startup_outcome.status = crate::agent_task::AgentTaskOutcomeStatus::Failed;
    startup_outcome.failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::Stalled);
    startup_outcome.diagnostics = vec![crate::agent_task::AgentTaskDiagnostic {
        class: "agent_task.provider_liveness_timeout".to_string(),
        message: "provider produced no observable progress before the liveness boundary"
            .to_string(),
        data: serde_json::json!({
            "provider": "generic-provider",
            "deadline": "liveness",
            "liveness_timeout_ms": 300_000,
            "timeout_ms": 1_230_000,
            "stdout_bytes": 0,
            "stderr_bytes": 0,
            "runtime_progress_events": 0,
            "workspace_progress_events": 0,
        }),
    }];
    aggregate.outcomes.push(startup_outcome);
    let mut report = cook_report(CookReportInput {
        cook_id: "startup-without-output-report".to_string(),
        status: "provider_failure",
        disposition: CookDisposition::Terminal,
        attempts: Vec::new(),
        finalization: None,
        stop_reason: None,
        exit_code: 1,
        invocation_latest_run_id: Some("startup-without-output-run"),
    });
    report.value.failure_context = Some(AgentTaskCookFailureContext {
        recovery_step: None,
        cook_id: "startup-without-output-report".to_string(),
        latest_run_id: "startup-without-output-run".to_string(),
        selected_run_id: None,
        selected_task_id: None,
        selected_candidate_sha: None,
        promotion_provenance: None,
        durable_recipe_ref: "homeboy://agent-task/cooks/startup-without-output-report/recipe"
            .to_string(),
        lifecycle_state: "Failed".to_string(),
        phase: "provider".to_string(),
        reason_code: "failed".to_string(),
        diagnostic: None,
        continuation_admission: None,
        blocking_claim: None,
        provider_budget_consumed: true,
        provider_executions_consumed: 1,
        recovery_legal: false,
        recovery_reason: "generic".to_string(),
        legal_actions: Vec::new(),
        next_actions: Vec::new(),
    });

    make_provider_timeout_actionable(
        None,
        &mut report,
        &aggregate,
        &plan,
        "startup-without-output-run",
        Some(AgentTaskExecutionBudget::new(1, 1, 0)),
        false,
    );
    make_provider_rotation_actionable(None, &mut report, &aggregate, "startup-without-output-run");
    make_startup_without_output_actionable(
        None,
        &mut report,
        &aggregate,
        "startup-without-output-run",
    );

    assert_eq!(report.value.status, "provider_failure");
    assert_eq!(
        report.value.terminal_failure_classification.as_deref(),
        Some("provider_startup_without_output")
    );
    assert_ne!(
        report.value.terminal_failure_classification.as_deref(),
        Some("provider_timeout")
    );
    let context = report
        .value
        .failure_context
        .expect("startup diagnostic context");
    assert_eq!(
        context.diagnostic.expect("diagnostic")["data"]["timeout_ms"],
        1_230_000
    );
    assert_eq!(
        context
            .legal_actions
            .iter()
            .map(|action| action.action.as_str())
            .collect::<Vec<_>>(),
        vec!["status", "diagnose"]
    );
    assert!(context
        .legal_actions
        .iter()
        .all(|action| !action.command.contains("--timeout-ms")));
}

#[test]
fn earlier_startup_liveness_diagnostic_does_not_overwrite_later_terminal_failure() {
    let plan = compile_options("later-terminal-failure")
        .identity
        .initial_plan;
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.status = crate::agent_task_scheduler::AgentTaskAggregateStatus::Failed;
    aggregate.outcomes[0].status = crate::agent_task::AgentTaskOutcomeStatus::Failed;
    aggregate.outcomes[0].failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::Stalled);
    aggregate.outcomes[0].diagnostics = vec![crate::agent_task::AgentTaskDiagnostic {
        class: "agent_task.provider_liveness_timeout".to_string(),
        message: "provider produced no observable progress before the liveness boundary"
            .to_string(),
        data: serde_json::json!({
            "deadline": "liveness",
            "stdout_bytes": 0,
            "stderr_bytes": 0,
            "runtime_progress_events": 0,
            "workspace_progress_events": 0,
        }),
    }];
    let mut later_failure = aggregate.outcomes[0].clone();
    later_failure.status = crate::agent_task::AgentTaskOutcomeStatus::Failed;
    later_failure.failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::ExecutionFailed);
    later_failure.diagnostics.clear();
    aggregate.outcomes.push(later_failure);
    let mut report = cook_report(CookReportInput {
        cook_id: "later-terminal-failure".to_string(),
        status: "provider_failure",
        disposition: CookDisposition::Terminal,
        attempts: Vec::new(),
        finalization: None,
        stop_reason: Some("later provider execution failed".to_string()),
        exit_code: 1,
        invocation_latest_run_id: Some("later-terminal-failure-run"),
    });
    report.value.terminal_phase = Some("provider".to_string());
    report.value.terminal_failure_classification = Some("provider_execution_failed".to_string());

    make_startup_without_output_actionable(
        None,
        &mut report,
        &aggregate,
        "later-terminal-failure-run",
    );

    assert_eq!(report.value.terminal_phase.as_deref(), Some("provider"));
    assert_eq!(
        report.value.terminal_failure_classification.as_deref(),
        Some("provider_execution_failed")
    );
    assert_eq!(
        report.value.stop_reason.as_deref(),
        Some("later provider execution failed")
    );
}

