fn persisted_review_budget_authority_preserves_lower_bounds_and_caps_larger_values() {
    let scope = CookFollowUpBudgetScope::FreshCookReview;
    let cook_budget = crate::agent_task_scheduler::AgentTaskExecutionBudget::new(9, 9, 9);
    let lower = serde_json::json!({
        "kind": "fresh_cook_review",
        "max_provider_executions": 1,
        "max_same_provider_retries": 0,
        "max_provider_rotations": 0,
        "review_plan_provider_executions": 0,
    });
    let (budget, _) = scoped_follow_up_budget(
        scope,
        &cook_budget,
        ExecutionBudgetUsage::default(),
        Some(&lower),
    );
    assert_eq!(
        budget,
        crate::agent_task_scheduler::AgentTaskExecutionBudget::new(1, 0, 0)
    );
    assert_eq!(review_budget_authority(scope, Some(&lower)), lower);

    let larger = serde_json::json!({
        "kind": "fresh_cook_review",
        "max_provider_executions": 99,
        "max_same_provider_retries": 99,
        "max_provider_rotations": 99,
        "review_plan_provider_executions": 99,
    });
    assert_eq!(
        review_budget_authority(scope, Some(&larger)),
        serde_json::json!({
            "kind": "fresh_cook_review",
            "max_provider_executions": 2,
            "max_same_provider_retries": 1,
            "max_provider_rotations": 0,
            "review_plan_provider_executions": 1,
        })
    );
}

#[test]
fn candidate_adoption_lifecycle_and_promotion_evidence_do_not_alias_across_explicit_roots() {
    let left_context = homeboy_core::test_support::HermeticTestContext::new();
    let right_context = homeboy_core::test_support::HermeticTestContext::new();
    let left_store = AgentTaskLifecycleStore::new(left_context.path_roots());
    let right_store = AgentTaskLifecycleStore::new(right_context.path_roots());
    let cook_id = "same-adoption-cook";
    let run_id = "same-adoption-run";
    let options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));

    for (store, candidate_sha, model, root) in [
        (&left_store, "left-candidate", "left-model", "left"),
        (&right_store, "right-candidate", "right-model", "right"),
    ] {
        store
            .submit_plan_with_runtime_admission(&options.identity.initial_plan, run_id, |_| {
                Ok(serde_json::json!({ "root": root }))
            })
            .unwrap();
        store.record_cook_attempt(cook_id, 1, run_id).unwrap();
        store
            .start_candidate_adoption_with_policy(
                run_id,
                candidate_sha,
                model,
                "verification",
                false,
                false,
            )
            .unwrap();
        store
            .checkpoint_candidate_adoption(run_id, "finalization", "finalize pull request")
            .unwrap();
        store
            .record_promotion(run_id, serde_json::json!({ "root": root }))
            .unwrap();
        store
            .record_candidate_adoption_result(run_id, serde_json::json!({ "root": root }))
            .unwrap();
        store.finish_candidate_adoption(run_id, None, true).unwrap();
    }

    for (store, candidate_sha, model, root) in [
        (&left_store, "left-candidate", "left-model", "left"),
        (&right_store, "right-candidate", "right-model", "right"),
    ] {
        let record = store.read_record(run_id).unwrap();
        let adoption = record.candidate_adoption.unwrap();
        assert_eq!(adoption.candidate_sha, candidate_sha);
        assert_eq!(adoption.ai_model, model);
        assert_eq!(adoption.result.unwrap()["root"], root);
        assert_eq!(
            record.metadata["cook_delivery"]["artifacts"]["promotion"]["root"],
            root
        );
    }

    assert_ne!(left_store.run_dir(run_id), right_store.run_dir(run_id));
    assert_ne!(left_store.cook_dir(cook_id), right_store.cook_dir(cook_id));
}

/// Seed a Cook attempt whose provider ran once and whose gate-green candidate
/// was promoted, ready for a finalization that the moving base blocks.
fn seed_moving_base_attempt(
    cook_id: &str,
    run_id: &str,
) -> (CookRequest, AgentTaskPromotionReport) {
    use crate::agent_task::{AgentTaskOutcome, AgentTaskOutcomeStatus};
    use crate::agent_task_scheduler::{
        AgentTaskAggregate, AgentTaskAggregateStatus, AgentTaskAggregateTotals,
        AgentTaskProgressEvent,
    };

    let mut options = batch_cook_options(
        cook_id,
        Arc::new(RecordingDetachedAttemptDispatcher {
            dispatches: Arc::new(AtomicUsize::new(0)),
        }),
    );
    options.identity.initial_run_id = run_id.to_string();
    options.finalization.no_finalize = false;
    options.provider_transport.provider_invocation =
        Some(homeboy_core::command_invocation::CommandInvocation {
            argv: vec!["fixture-provider".to_string()],
            ..Default::default()
        });
    options.gates = VerifyGateOptions {
        verify: vec!["public gate".to_string()],
        private_verify: vec!["private gate".to_string()],
        private_gate_reveal: crate::agent_task_gate::AgentTaskGateRevealPolicy::FullEvidence,
        ..Default::default()
    };
    options.workspace.to_worktree = "homeboy@8058".to_string();
    persist_initial_recipe(&options).expect("persist moving-base recipe");
    agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id)).unwrap();
    agent_task_lifecycle::record_cook_attempt_in_store(
        &test_lifecycle_store(),
        &options.identity.cook_id,
        1,
        run_id,
    )
    .expect("index moving-base attempt");
    agent_task_lifecycle::record_run_aggregate(
        run_id,
        &options.identity.initial_plan,
        &AgentTaskAggregate {
            schema: crate::agent_task::AGENT_TASK_AGGREGATE_SCHEMA.to_string(),
            plan_id: options.identity.initial_plan.plan_id.clone(),
            status: AgentTaskAggregateStatus::Succeeded,
            totals: AgentTaskAggregateTotals {
                succeeded: 1,
                ..Default::default()
            },
            outcomes: vec![AgentTaskOutcome {
                task_id: "provider".to_string(),
                status: AgentTaskOutcomeStatus::Succeeded,
                summary: Some("provider dispatched once".to_string()),
                outputs: test_review_form_outputs(),
                metadata: serde_json::json!({ "model": "fixture-model" }),
                ..Default::default()
            }],
            events: vec![AgentTaskProgressEvent {
                task_id: "provider".to_string(),
                state: AgentTaskState::Succeeded,
                attempt: 1,
                message: None,
            }],
            artifact_lineage: Vec::new(),
            child_runs: Vec::new(),
            artifact_bindings: Vec::new(),
            queue: Default::default(),
        },
    )
    .unwrap();
    let mut applied = promotion(run_id);
    applied.provenance["candidate"] =
        serde_json::json!({"kind":"git","fingerprint":{"tree":"before"}});
    agent_task_lifecycle::record_promotion(run_id, serde_json::to_value(&applied).unwrap())
        .unwrap();
    agent_task_lifecycle::rewrite_record_for_test(run_id, |record| {
        record.metadata["provider_executions_consumed"] = serde_json::json!(1);
    })
    .unwrap();
    (options, applied)
}

/// #15112: a Cook dispatched without `--model` executes under the provider's
/// resolved default. Seed a terminal attempt whose selected outcome never
/// recorded `metadata.model` so promotion must resolve the executed model from
/// the attempt's remaining durable evidence.
fn seed_default_model_attempt(
    cook_id: &str,
    run_id: &str,
    outcome: crate::agent_task::AgentTaskOutcome,
) -> CookRequest {
    use crate::agent_task_scheduler::{
        AgentTaskAggregate, AgentTaskAggregateStatus, AgentTaskAggregateTotals,
        AgentTaskProgressEvent,
    };

    let mut options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
    options.identity.initial_run_id = run_id.to_string();
    agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id))
        .expect("submit default-model attempt");
    agent_task_lifecycle::record_run_aggregate(
        run_id,
        &options.identity.initial_plan,
        &AgentTaskAggregate {
            schema: crate::agent_task::AGENT_TASK_AGGREGATE_SCHEMA.to_string(),
            plan_id: options.identity.initial_plan.plan_id.clone(),
            status: AgentTaskAggregateStatus::Succeeded,
            totals: AgentTaskAggregateTotals {
                succeeded: 1,
                ..Default::default()
            },
            outcomes: vec![outcome],
            events: vec![AgentTaskProgressEvent {
                task_id: "provider".to_string(),
                state: AgentTaskState::Succeeded,
                attempt: 1,
                message: None,
            }],
            artifact_lineage: Vec::new(),
            child_runs: Vec::new(),
            artifact_bindings: Vec::new(),
            queue: Default::default(),
        },
    )
    .expect("record default-model aggregate");
    options
}

fn modelless_outcome(
    outputs: serde_json::Value,
    artifacts: Vec<crate::agent_task::AgentTaskArtifact>,
) -> crate::agent_task::AgentTaskOutcome {
    crate::agent_task::AgentTaskOutcome {
        task_id: "provider".to_string(),
        status: crate::agent_task::AgentTaskOutcomeStatus::Succeeded,
        summary: Some("provider resolved its own default model".to_string()),
        outputs,
        artifacts,
        metadata: serde_json::Value::Null,
        ..Default::default()
    }
}

fn selected_outcome_of(run_id: &str) -> crate::agent_task::AgentTaskOutcome {
    test_lifecycle_store()
        .read_aggregate(run_id)
        .expect("seeded aggregate")
        .outcomes
        .first()
        .cloned()
        .expect("seeded outcome")
}

/// #15112 (local placement): the scheduler's durable provider execution ledger
/// recorded the executed model even though the normalized outcome lost it.
#[test]
fn promotion_resolves_executed_model_from_local_provider_execution_ledger() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let run_id = "cook-15112-local-run";
        seed_default_model_attempt(
            "cook-15112-local",
            run_id,
            modelless_outcome(serde_json::Value::Null, Vec::new()),
        );
        agent_task_lifecycle::rewrite_record_for_test(run_id, |record| {
            record.metadata["provider_executions"] = serde_json::json!([{
                "key": "provider:1",
                "task_id": "provider",
                "attempt": 1,
                "state": "succeeded",
                "model": "anthropic/claude-sonnet-5",
            }]);
        })
        .expect("record executed-model ledger");

        let model = promotion_executed_model_in_store(
            &test_lifecycle_store(),
            run_id,
            &selected_outcome_of(run_id),
        )
        .expect("ledger-backed attempt promotes");

        assert_eq!(model, "anthropic/claude-sonnet-5");
    });
}

/// #15112 (Lab placement): the candidate harvested from the runner carries the
