#[test]
fn execution_step_reservation_before_recipe_and_index_repairs_and_executes_provider_once() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let options = retryable_pre_provider_cook("cook-reservation-boundary", 2);
        let reserved = format!("{}-retry", options.identity.initial_run_id);
        let store = test_lifecycle_store();
        let marker = home.path().join("reservation-committed");
        kill_test_child_at_marker(
            "agent_task_service::cook::tests::execution_step_reservation_crash_entry",
            &[("S8_RESERVATION_MARKER", marker.as_os_str())],
            &marker,
        );
        // Reopen both durable stores before repairing the killed caller's
        // reservation. Lost admission/ACK replay selects the same daemon job.
        crate::agent_task_service::register_execution_step_hooks();
        let intent = current_intent(&store, &reserved);
        let path = store.data_root().join("reservation-jobs.sqlite");
        let harness = step_harness(&intent, &path, "reservation-original");
        let admitted = harness
            .admit_keyed(intent.step.submission().unwrap())
            .unwrap();
        let restarted = harness.reopen(&path, "reservation-restarted").unwrap();
        assert_eq!(
            restarted
                .admit_keyed(intent.step.submission().unwrap())
                .unwrap()
                .id,
            admitted.id
        );
        store
            .open_observation_initialized()
            .unwrap()
            .acknowledge_work_intent(
                &intent.intent_id,
                &serde_json::json!({"scheduled": true, "job_id": admitted.id.to_string()}),
            )
            .unwrap();
        assert_eq!(
            super::super::load_recipe(&options.identity.cook_id)
                .unwrap()
                .attempts
                .len(),
            1
        );
        assert_eq!(
            store
                .read_cook_index(&options.identity.cook_id)
                .unwrap()
                .latest_run_id,
            options.identity.initial_run_id
        );
        let frozen = store.read_controller_plan(&reserved).unwrap();
        let starts = Arc::new(AtomicUsize::new(0));
        for _ in 0..2 {
            execute_reserved_retry_fixture(
                &reserved,
                Arc::new(RecordingImmediateSuccessExecutor {
                    starts: starts.clone(),
                }),
            );
        }
        assert_eq!(starts.load(Ordering::SeqCst), 1);
        let recipe = super::super::load_recipe(&options.identity.cook_id).unwrap();
        assert_eq!(recipe.attempts.len(), 2);
        assert_eq!(recipe.attempts[1].run_id, reserved);
        assert_eq!(
            recipe.attempts[1].attempt, 1,
            "transport replacement retains the provider attempt"
        );
        assert_eq!(recipe.attempts[1].plan, frozen);
        assert_eq!(
            store
                .read_cook_index(&options.identity.cook_id)
                .unwrap()
                .latest_run_id,
            reserved
        );
        assert_eq!(
            store.read_record(&reserved).unwrap().metadata["provider_executions_consumed"],
            1
        );
        assert_eq!(agent_task_lifecycle::list_records().unwrap().len(), 2);
    });
}

#[test]
fn retryable_pre_provider_retry_concurrently_claims_one_successor() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let options = retryable_pre_provider_cook("cook-retry-concurrent", 2);
        let barrier = Arc::new(Barrier::new(4));
        let retries = (0..4)
            .map(|_| {
                let barrier = Arc::clone(&barrier);
                let run_id = options.identity.initial_run_id.clone();
                std::thread::spawn(move || {
                    barrier.wait();
                    let retry = crate::agent_task_service::retry(&run_id, None, false, false)
                        .expect("concurrent retry converges");
                    (retry.record.run_id, retry.created)
                })
            })
            .collect::<Vec<_>>();
        let run_ids = retries
            .into_iter()
            .map(|retry| retry.join().expect("retry thread"))
            .collect::<Vec<_>>();

        assert!(run_ids.iter().all(|(run_id, _)| run_id == &run_ids[0].0));
        assert_eq!(
            run_ids.iter().filter(|(_, created)| *created).count(),
            1,
            "only the reservation owner may launch the local retry child"
        );
        let recipe = super::super::load_recipe(&options.identity.cook_id).expect("bound recipe");
        let index =
            agent_task_lifecycle::cook_index(&options.identity.cook_id).expect("bound index");
        assert_eq!(recipe.attempts.len(), 2);
        assert_eq!(recipe.attempts[1].run_id, run_ids[0].0.as_str());
        assert_eq!(index.attempts.len(), 2);
        assert_eq!(index.latest_run_id, run_ids[0].0.as_str());
        assert_eq!(
            agent_task_lifecycle::list_records()
                .expect("durable lifecycle records")
                .len(),
            2,
            "the source and one bound successor are the only durable runs"
        );
    });
}

