#[test]
fn cook_repairs_initial_alias_after_submit_before_index_interruption() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let cook_id = "cook-repair-initial-alias";
        let run_id = "cook-repair-initial-alias-run";
        let options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
        super::super::persist_initial_recipe(&options).expect("persist durable recipe");

        // Simulate a controller crash after plan submission and before the
        // subsequent Cook attempt index write.
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id))
            .expect("persist initial run");
        assert!(agent_task_lifecycle::cook_index(cook_id).is_err());

        let observed = Arc::new(Mutex::new(Vec::new()));
        let observer_records = observed.clone();
        let result = run_cook(CookContext {
            durable_observer: Some(&move |event: &CookProgressEvent<'_>| {
                let (phase, cook, run) = (event.phase, event.cook_id, event.run_id);
                let status = agent_task_lifecycle::reconcile_status(cook)
                    .expect("Cook alias resolves in observer");
                let logs =
                    agent_task_lifecycle::logs(cook).expect("Cook alias logs resolve in observer");
                assert_eq!(status.run_id, run);
                assert!(!logs.events.is_empty());
                observer_records
                    .lock()
                    .expect("observer records lock")
                    .push((phase.to_string(), cook.to_string(), run.to_string()));
                Ok(())
            }),
            ..CookContext::new(options, Arc::new(UnusedExecutor))
        })
        .expect("restart repairs the Cook alias");

        assert_eq!(result.value.latest_run_id.as_deref(), Some(run_id));
        assert_eq!(
            observed.lock().expect("observer records lock").as_slice(),
            &[
                (
                    "durable_identity".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
                (
                    "workspace_provider_canonicalization".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
                (
                    "workspace_base_capture".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
                (
                    "workspace_disk_pressure".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
                (
                    "provider_ready".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
                (
                    "provider_start".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
                (
                    "in_flight".to_string(),
                    cook_id.to_string(),
                    run_id.to_string()
                ),
            ]
        );
        assert_eq!(
            agent_task_lifecycle::reconcile_status(run_id)
                .expect("durable progress")
                .metadata["cook_progress"]["phase"],
            "in_flight"
        );
        let index = agent_task_lifecycle::cook_index(cook_id).expect("repaired Cook index");
        assert_eq!(index.latest_run_id, run_id);
        assert_eq!(index.attempts.len(), 1);
        assert_eq!(index.attempts[0].attempt, 1);
        assert_eq!(index.attempts[0].run_id, run_id);
        assert_eq!(
            agent_task_lifecycle::reconcile_status(cook_id)
                .expect("Cook alias status after restart")
                .run_id,
            run_id
        );
        assert!(agent_task_lifecycle::logs(cook_id).is_ok());
        crate::agent_task_service::retry(
            run_id,
            Some("cook-repair-initial-alias-retry"),
            false,
            false,
        )
        .expect_err("an accepted initial attempt must not reserve a parallel retry");
        assert_eq!(
            agent_task_lifecycle::cook_index(cook_id)
                .unwrap()
                .attempts
                .len(),
            1
        );
    });
}

/// Fails at the exact controller boundary where Lab materialization begins,
/// after recording whether the durable run record was already addressable by
/// id at that moment. Models the caller-timeout case in #9163/#10419.
#[derive(Debug)]
struct MaterializationInterruptingDispatcher {
    run_id: String,
    state_at_materialization: Arc<Mutex<Option<String>>>,
}

impl AgentTaskCookAttemptDispatcher for MaterializationInterruptingDispatcher {
    fn durable_recipe(&self) -> Result<Value> {
        Ok(serde_json::json!({ "kind": "test-materialization-interruption" }))
    }

    fn prepare_for_cook(&self) -> Result<()> {
        // Controller-side Lab materialization starts here. The durable record
        // must already resolve by id, or an interruption from this point on
        // strands an unnamed reservation.
        let record = agent_task_lifecycle::reconcile_status(&self.run_id)?;
        *self
            .state_at_materialization
            .lock()
            .expect("materialization state") = Some(format!("{:?}", record.state()));
        Err(
            Error::internal_unexpected("fixture caller was interrupted during Lab materialization")
                .with_retryable(true),
        )
    }

    fn dispatch_attempt(
        &self,
        _plan: AgentTaskPlan,
        _run_id: &str,
        _derived_cook_baseline: Option<&DerivedCookBaselineCapability>,
    ) -> Result<()> {
        panic!("an interrupted materialization must never reach provider dispatch")
    }
}

#[test]
fn cook_publishes_durable_identity_before_materialization_and_survives_interruption() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let cook_id = "cook-durable-identity-first";
        let run_id = "cook-durable-identity-first-run";
        let state_at_materialization = Arc::new(Mutex::new(None));
        let options = batch_cook_options(
            cook_id,
            Arc::new(MaterializationInterruptingDispatcher {
                run_id: run_id.to_string(),
                state_at_materialization: state_at_materialization.clone(),
            }),
        );

        let observed = Arc::new(Mutex::new(Vec::new()));
        let observer_records = observed.clone();
        let result = run_cook(CookContext {
            durable_observer: Some(&move |event: &CookProgressEvent<'_>| {
                let (phase, cook, run) = (event.phase, event.cook_id, event.run_id);
                observer_records
                    .lock()
                    .expect("observer records lock")
                    .push((phase.to_string(), run.to_string()));
                // Every identity-bearing event must be immediately actionable:
                // the caller can look the run up the moment it is told about it.
                assert_eq!(
                    agent_task_lifecycle::reconcile_status(cook)
                        .expect("Cook alias resolves in observer")
                        .run_id,
                    run
                );
                Ok(())
            }),
            ..CookContext::new(options, Arc::new(UnusedExecutor))
        })
        .expect("interrupted materialization returns a durable report");

        // 1. Identity is published before any materialization work.
        assert_eq!(
            observed
                .lock()
                .expect("observer records lock")
                .first()
                .cloned(),
            Some(("durable_identity".to_string(), run_id.to_string()))
        );

        // 2. The record was findable by id at the instant materialization began.
        assert_eq!(
            state_at_materialization
                .lock()
                .expect("materialization state")
                .as_deref(),
            Some("Queued")
        );

        // 3. The interruption left a named, recoverable record — not an
        //    anonymous reservation an operator has to hunt for.
        assert_eq!(result.value.status, "pre_execution_failure");
        let record =
            agent_task_lifecycle::reconcile_status(run_id).expect("record survives interruption");
        assert_eq!(
            record.metadata["pre_execution_failure"]["phase"],
            serde_json::json!("cook_pre_execution")
        );
        assert_eq!(
            agent_task_lifecycle::reconcile_status(cook_id)
                .expect("Cook alias resolves after interruption")
                .run_id,
            run_id
        );
        assert!(agent_task_lifecycle::logs(run_id).is_ok());
        // Recoverable, not merely observable: the operator can act on the id.
        crate::agent_task_service::retry(
            run_id,
            Some("cook-durable-identity-first-retry"),
            false,
            false,
        )
        .expect("interrupted zero-execution materialization reserves a prepared retry");
    });
}

#[test]
fn cook_persists_identity_before_fallible_workspace_canonicalization() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let workspace = tempfile::tempdir().expect("workspace root");
        let cook_id = "cook-canonicalization-admission";
        let run_id = "cook-canonicalization-admission-run";
        let mut options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
        options.identity.initial_run_id = run_id.to_string();
        options.workspace.source_worktree_path = Some(workspace.path().join("missing"));

        let first = run_cook(CookContext::new(options.clone(), Arc::new(UnusedExecutor)))
            .expect("canonicalization failure has a durable Cook report");
        assert_eq!(first.value.status, "pre_execution_failure");
        assert_eq!(
            agent_task_lifecycle::reconcile_status(cook_id)
                .expect("Cook alias resolves after canonicalization failure")
                .run_id,
            run_id
        );
        let record = agent_task_lifecycle::reconcile_status(run_id)
            .expect("canonicalization failure persists its attempt");
        assert_eq!(
            record.state(),
            agent_task_lifecycle::AgentTaskRunState::Failed
        );
        assert_eq!(
            record.metadata["cook_progress"]["phase"],
            serde_json::json!("workspace_provider_canonicalization")
        );

        let replay = run_cook(CookContext::new(options, Arc::new(UnusedExecutor)))
            .expect("replay returns the same durable Cook failure");
        assert_eq!(replay.value.status, first.value.status);
        assert_eq!(
            agent_task_lifecycle::reconcile_status(cook_id)
                .expect("replay preserves Cook alias")
                .run_id,
            run_id
        );
    });
}

#[test]
fn replayed_materialized_attempt_terminalizes_when_canonicalization_fails() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let workspace = tempfile::tempdir().expect("workspace root");
        let cook_id = "cook-replayed-canonicalization-admission";
        let run_id = "cook-replayed-canonicalization-admission-run";
        let mut options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
        options.identity.initial_run_id = run_id.to_string();
        options.workspace.source_worktree_path = Some(workspace.path().join("missing"));

        // Simulate interruption after materialization but before the startup
        // canonicalization phase. Replay must not leave this queued forever.
        persist_initial_recipe(&options).expect("persist recipe before interruption");
        let recipe_store = CookRecipeStore::from_current_data_root().expect("recipe store");
        let lifecycle_store = test_lifecycle_store();
        recover_recipe_attempt_with_stores(&recipe_store, &lifecycle_store, run_id)
            .expect("materialize interrupted attempt");
        assert_eq!(
            lifecycle_store
                .read_record(run_id)
                .expect("queued replay record")
                .state(),
            AgentTaskRunState::Queued
        );

        let replay = run_cook(CookContext::new(options, Arc::new(UnusedExecutor)))
            .expect("replay returns durable canonicalization failure");
        assert_eq!(replay.value.status, "pre_execution_failure");
        let record = lifecycle_store
            .read_record(run_id)
            .expect("terminal replay record");
        assert_eq!(record.state(), AgentTaskRunState::Failed);
        assert!(record.metadata.get("pre_execution_failure").is_some());
    });
}

#[test]
fn local_startup_base_capture_is_durable_and_reported_before_interruption() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let temp = tempfile::tempdir().expect("temporary repository");
        let repository = temp.path().join("repository");
        std::fs::create_dir(&repository).expect("create repository");
        let git = |args: &[&str]| {
            assert!(Command::new("git")
                .args(args)
                .current_dir(&repository)
                .status()
                .expect("run git")
                .success());
        };
        git(&["init", "-b", "main"]);
        std::fs::write(repository.join("fixture.txt"), "base\n").expect("write base");
        git(&["add", "fixture.txt"]);
        git(&[
            "-c",
            "user.name=Homeboy Test",
            "-c",
            "user.email=test@example.com",
            "commit",
            "-m",
            "base",
        ]);
        git(&[
            "remote",
            "add",
            "origin",
            repository.to_str().expect("repository path"),
        ]);
        let worktree = temp.path().join("worktree");
        git(&[
            "worktree",
            "add",
            "--detach",
            worktree.to_str().expect("worktree path"),
            "HEAD",
        ]);

        let cook_id = "cook-local-startup-base-capture";
        let run_id = format!("{cook_id}-run");
        let mut options = batch_cook_options(
            cook_id,
            Arc::new(MaterializationInterruptingDispatcher {
                run_id: run_id.clone(),
                state_at_materialization: Arc::new(Mutex::new(None)),
            }),
        );
        options.identity.initial_run_id = run_id.clone();
        options.workspace.to_worktree = worktree.display().to_string();
        options.workspace.source_worktree_path = Some(worktree.clone());
        options.identity.initial_plan.tasks[0].workspace.root =
            Some(worktree.display().to_string());

        let hook = Arc::new(WorkspaceBaseCaptureHook {
            workspace: worktree,
            count: AtomicUsize::new(0),
            fail_after_recipe_persistence: AtomicBool::new(true),
        });
        *WORKSPACE_BASE_CAPTURE_HOOK
            .lock()
            .expect("install workspace base capture interruption") = Some(Arc::clone(&hook));
        let observed = Arc::new(Mutex::new(Vec::new()));
        let observer_records = Arc::clone(&observed);
        let result = run_cook(CookContext {
            durable_observer: Some(&move |event: &CookProgressEvent<'_>| {
                observer_records
                    .lock()
                    .expect("observer records lock")
                    .push((event.phase.to_string(), event.detail.map(str::to_string)));
                assert_eq!(
                    agent_task_lifecycle::reconcile_status(event.cook_id)
                        .expect("announced Cook alias resolves")
                        .run_id,
                    event.run_id
                );
                Ok(())
            }),
            ..CookContext::new(options, Arc::new(UnusedExecutor))
        })
        .expect("startup interruption produces a durable report");
        *WORKSPACE_BASE_CAPTURE_HOOK
            .lock()
            .expect("remove workspace base capture interruption") = None;

        let observed = observed.lock().expect("observer records lock");
        assert_eq!(
            observed.first().map(|event| event.0.as_str()),
            Some("durable_identity")
        );
        assert!(
            observed.iter().any(|(phase, detail)| {
                phase == "workspace_base_capture"
                    && detail.as_deref() == Some("starting; elapsed=0s")
            }),
            "startup base capture must be named with bounded elapsed detail: {observed:?}"
        );
        assert_eq!(hook.count.load(Ordering::SeqCst), 1);
        assert_eq!(result.value.status, "pre_execution_failure");
        let record = agent_task_lifecycle::reconcile_status(&run_id)
            .expect("interrupted startup remains status-addressable");
        assert!(record.state().is_terminal());
        assert!(agent_task_lifecycle::logs(cook_id).is_ok());
    });
}

