#[test]
fn cook_ignores_untrusted_or_malformed_lab_runtime_recovery_metadata() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let cook_id = "cook-untrusted-runtime-recovery";
        let options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
        persist_initial_recipe(&options).expect("persist recipe");
        agent_task_lifecycle::submit_plan(
            &options.identity.initial_plan,
            Some(&options.identity.initial_run_id),
        )
        .expect("persist current invocation");
        agent_task_lifecycle::record_cook_attempt_in_store(
            &test_lifecycle_store(),
            cook_id,
            1,
            &options.identity.initial_run_id,
        )
        .expect("index current invocation");

        for metadata in [
            serde_json::json!({
                "phase": "lab_staging_controller",
                "details": {
                    "homeboy_handoff_identity": {
                        "recovery_command": "arbitrary command"
                    }
                }
            }),
            serde_json::json!({
                "phase": "lab_staging_controller",
                "details": {
                    "lab_handoff_runtime_recovery": {
                        "schema": "homeboy/agent-task-lab-runtime-recovery/v1",
                        "runner_id": "homeboy-lab",
                        "requested_build_identity": "homeboy 1.2.3+required"
                    }
                }
            }),
            serde_json::json!({
                "phase": "controller_admission",
                "details": {
                    "lab_handoff_runtime_recovery": {
                        "schema": "homeboy/agent-task-lab-runtime-recovery/v1",
                        "runner_id": "homeboy-lab",
                        "requested_build_identity": "homeboy 1.2.3+required",
                        "build_ref": "required"
                    }
                }
            }),
        ] {
            agent_task_lifecycle::rewrite_record_for_test(
                &options.identity.initial_run_id,
                |record| {
                    record.metadata["pre_execution_failure"] = metadata.clone();
                },
            )
            .expect("persist adversarial metadata");
            let report = cook_report(CookReportInput {
                cook_id: cook_id.to_string(),
                status: "pre_execution_failure",
                disposition: CookDisposition::Terminal,
                attempts: Vec::new(),
                finalization: None,
                stop_reason: None,
                exit_code: 1,
                invocation_latest_run_id: Some(&options.identity.initial_run_id),
            });
            assert!(report
                .value
                .failure_context
                .expect("failure context")
                .legal_actions
                .iter()
                .all(|action| action.action != "refresh_lab_runtime"));
        }
    });
}

#[test]
fn cook_retries_retryable_pre_provider_transport_failures_within_attempt_budget() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let dispatches = Arc::new(AtomicUsize::new(0));
        let runner_jobs_created = Arc::new(AtomicUsize::new(0));
        let cook_id = "cook-retryable-transport";
        let mut options = batch_cook_options(
            cook_id,
            Arc::new(RetryableTransportFailingAttemptDispatcher {
                dispatches: Arc::clone(&dispatches),
                runner_jobs_created: Arc::clone(&runner_jobs_created),
            }),
        );
        options.provider_transport.provider_invocation =
            Some(homeboy_core::command_invocation::CommandInvocation {
                argv: vec!["fixture-provider".to_string()],

                ..Default::default()
            });
        options.identity.initial_run_id = "cook-retryable-transport-attempt-1".to_string();
        options.retry_policy.max_attempts = 2;

        let result = run_cook(CookContext::new(options, Arc::new(UnusedExecutor)))
            .expect("cook records transport retries");

        assert_eq!(result.exit_code, 1);
        assert_eq!(result.value.status, "pre_execution_failure");
        assert_eq!(result.value.attempts.len(), 2);
        assert_eq!(dispatches.load(Ordering::SeqCst), 2);
        assert_eq!(runner_jobs_created.load(Ordering::SeqCst), 0);
        assert_eq!(result.value.history_run_ids.len(), 2);
        assert_eq!(
            result.value.history_run_ids[0],
            "cook-retryable-transport-attempt-1"
        );
        assert!(result.value.history_run_ids[1]
            .starts_with("cook-retryable-transport-attempt-1-transport-retry"));
        assert!(result
            .value
            .attempts
            .iter()
            .all(|attempt| attempt.attempt == 1));
        let recipe = super::super::load_recipe(cook_id).expect("transport retries are durable");
        assert_eq!(recipe.attempts.len(), 2);
        assert!(recipe.attempts.iter().all(|attempt| attempt.attempt == 1));
        let observation_store = test_lifecycle_store()
            .open_observation_initialized()
            .expect("observation store");
        for (transport_attempt, run_id) in result.value.history_run_ids.iter().enumerate() {
            let record =
                agent_task_lifecycle::reconcile_status(run_id).expect("retry attempt exists");
            let observation = observation_store
                .get_run(run_id)
                .expect("read retry observation")
                .expect("retry observation exists");
            assert_eq!(
                observation.homeboy_version.as_deref(),
                Some(homeboy_core::build_identity::current().version.as_str())
            );
            assert_eq!(
                record.metadata["controller_identity"],
                homeboy_core::build_identity::current().display
            );
            assert!(record.provider_handles.is_empty());
            assert!(record.lab_handoff.is_none());
            assert!(record.runner_job_id().is_none());
            assert_eq!(record.runner_id(), Some("fixture-lab"));
            assert_eq!(record.metadata["provider_executions_consumed"], 0);
            assert_eq!(record.metadata["pre_execution_failure"]["retryable"], true);
            assert_eq!(
                record.metadata["pre_execution_failure"]["failure_classification"],
                "transient"
            );
            let receipt: LabTransportAttemptReceipt = serde_json::from_value(
                record.metadata["pre_execution_failure"]["details"]
                    ["lab_transport_attempt_receipt"]
                    .clone(),
            )
            .expect("durable typed transport receipt");
            assert_eq!(receipt.transport_attempt as usize, transport_attempt);
            assert_eq!(receipt.transport_retry_limit, 1);
            assert_eq!(receipt.selected_runner, "fixture-lab");
            assert_eq!(receipt.error.kind, LabTransportErrorKind::BrokenPipe);
            assert_eq!(
                receipt.acceptance,
                LabJobAcceptanceDisposition::NoJobAccepted
            );
            assert!(receipt.receipt_id.starts_with(run_id));
            assert!(!serde_json::to_string(&record)
                .expect("serialize durable record")
                .contains("fixture-preacceptance-secret"));
        }
    });
}

#[test]
fn cook_transport_retry_owner_projects_retry_eligibility_without_provider() {
    use homeboy_control_plane_contract::{ControlPlaneAction, ControlPlaneActionAvailability};

    homeboy_core::test_support::with_isolated_home(|_| {
        let options = retryable_pre_provider_cook("cook-transport-projection", 2);
        agent_task_lifecycle::rewrite_record_for_test(&options.identity.initial_run_id, |record| {
            record.metadata["provider_executions_consumed"] = serde_json::json!(1);
        })
        .expect("make the predecessor budget-consuming");
        let semantic_retry =
            crate::agent_task_service::retry(&options.identity.initial_run_id, None, false, false)
                .expect("materialize the semantic Cook retry");
        agent_task_lifecycle::record_pre_execution_failure(
            &semantic_retry.record.run_id,
            &options.identity.initial_plan,
            "lab_handoff",
            &Error::internal_io("transport failed", None).with_retryable(true),
        )
        .expect("terminalize the semantic retry before its transport replacement");

        let transport_run_id = format!("{}-transport-retry", semantic_retry.record.run_id);
        super::super::cook_recipe::default_store()
            .expect("Cook recipe store")
            .record_recipe_attempt_replacement(
                &options.identity.cook_id,
                &semantic_retry.record.run_id,
                &transport_run_id,
            )
            .expect("persist the transport replacement");
        let transport_retry =
            crate::agent_task_service::retry(&options.identity.initial_run_id, None, true, true)
                .expect("materialize the Cook transport retry child");
        assert!(transport_retry.record.run_id.ends_with("-transport-retry"));
        assert!(transport_retry.record.provider_handles.is_empty());
        agent_task_lifecycle::record_pre_execution_failure(
            &transport_retry.record.run_id,
            &options.identity.initial_plan,
            "lab_handoff",
            &Error::internal_io("transport failed again", None).with_retryable(true),
        )
        .expect("terminalize the transport retry child");

        let projected =
            crate::orchestration::run_from_current_environment(&transport_retry.record.run_id)
                .expect("project the Cook transport retry child");
        let retry = projected
            .action_eligibility
            .expect("projected action eligibility")
            .actions
            .into_iter()
            .find(|action| action.action == ControlPlaneAction::Retry)
            .expect("retry action");
        assert_eq!(
            retry.availability,
            ControlPlaneActionAvailability::Available
        );
    });
}

#[test]
fn cook_reattests_each_initial_baseline_before_detached_transport_retry() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let temp = tempfile::tempdir().expect("temporary repository root");
        let primary = temp.path().join("primary");
        let source = temp.path().join("source");
        std::fs::create_dir(&primary).expect("create primary repository");
        let git = |cwd: &std::path::Path, args: &[&str]| {
            let output = Command::new("git")
                .args(args)
                .current_dir(cwd)
                .output()
                .expect("run git fixture command");
            assert!(output.status.success(), "git {:?} failed", args);
        };
        git(&primary, &["init", "--initial-branch=main"]);
        git(&primary, &["config", "user.email", "agent@example.test"]);
        git(&primary, &["config", "user.name", "Agent"]);
        std::fs::write(primary.join("fixture.txt"), "base\n").expect("write base fixture");
        git(&primary, &["add", "fixture.txt"]);
        git(&primary, &["commit", "-m", "base"]);
        git(
            &primary,
            &[
                "remote",
                "add",
                "origin",
                primary.to_str().expect("UTF-8 primary path"),
            ],
        );
        git(
            &primary,
            &["fetch", "origin", "main:refs/remotes/origin/main"],
        );
        git(
            &primary,
            &[
                "worktree",
                "add",
                "--detach",
                source.to_str().expect("UTF-8 source path"),
                "HEAD",
            ],
        );
        std::fs::write(source.join("fixture.txt"), "candidate\n").expect("write candidate fixture");

        let observations = Arc::new(Mutex::new(Vec::new()));
        let mut options = batch_cook_options(
            "cook-baseline-attestation",
            Arc::new(AttestingRetryableTransportDispatcher {
                observations: Arc::clone(&observations),
            }),
        );
        options.identity.initial_run_id = "cook-baseline-attestation-attempt-1".to_string();
        options.workspace.to_worktree = source.display().to_string();
        options.workspace.source_worktree_path = Some(source.clone());
        options.provider_transport.provider_invocation =
            Some(homeboy_core::command_invocation::CommandInvocation {
                argv: vec!["fixture-provider".to_string()],

                ..Default::default()
            });
        options.identity.initial_plan.tasks[0].workspace.root = Some(source.display().to_string());
        let source_identity = crate::agent_task_workspace_identity::attest_workspace(&source)
            .expect("attest admitted source workspace");
        options.identity.initial_plan.tasks[0].metadata["cook_workspace_identity"] =
            source_identity.clone();

        let result = run_cook(CookContext::new(options, Arc::new(UnusedExecutor)))
            .expect("record bounded transport retry");

        assert_eq!(result.value.attempts.len(), 2);
        let observations = observations.lock().expect("baseline observations");
        assert_eq!(observations.len(), 2);
        assert!(observations.iter().all(|(_, _, _, matches)| *matches));
        assert_ne!(observations[0].0, observations[1].0);
        assert!(observations
            .iter()
            .all(|(_, _, predecessor, _)| predecessor == &source_identity));
    });
}

/// Regression for #15815: a first-attempt Cook with a dirty candidate gets a
/// controller-owned baseline worktree that is handed to a detached dispatcher.
/// Lab staging reads it after `dispatch_attempt` returns, so the baseline must
/// still exist after the dispatch scope ends (the retry path got the same fix
/// in #15379).
#[test]
fn first_attempt_initial_baseline_outlives_detached_dispatch() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let temp = tempfile::tempdir().expect("temporary repository root");
        let primary = temp.path().join("primary");
        let source = temp.path().join("source");
        std::fs::create_dir(&primary).expect("create primary repository");
        let git = |cwd: &std::path::Path, args: &[&str]| {
            let output = Command::new("git")
                .args(args)
                .current_dir(cwd)
                .output()
                .expect("run git fixture command");
            assert!(output.status.success(), "git {:?} failed", args);
        };
        git(&primary, &["init", "--initial-branch=main"]);
        git(&primary, &["config", "user.email", "agent@example.test"]);
        git(&primary, &["config", "user.name", "Agent"]);
        std::fs::write(primary.join("fixture.txt"), "base\n").expect("write base fixture");
        git(&primary, &["add", "fixture.txt"]);
        git(&primary, &["commit", "-m", "base"]);
        git(
            &primary,
            &[
                "remote",
                "add",
                "origin",
                primary.to_str().expect("UTF-8 primary path"),
            ],
        );
        git(
            &primary,
            &["fetch", "origin", "main:refs/remotes/origin/main"],
        );
        git(
            &primary,
            &[
                "worktree",
                "add",
                "--detach",
                source.to_str().expect("UTF-8 source path"),
                "HEAD",
            ],
        );
        std::fs::write(source.join("fixture.txt"), "candidate\n").expect("write candidate fixture");

        let roots = Arc::new(Mutex::new(Vec::new()));
        let mut options = batch_cook_options(
            "cook-initial-baseline-lifetime",
            Arc::new(BaselineCapturingDetachedDispatcher {
                roots: Arc::clone(&roots),
            }),
        );
        options.identity.initial_run_id = "cook-initial-baseline-lifetime-attempt-1".to_string();
        options.workspace.to_worktree = source.display().to_string();
        options.workspace.source_worktree_path = Some(source.clone());
        options.provider_transport.provider_invocation =
            Some(homeboy_core::command_invocation::CommandInvocation {
                argv: vec!["fixture-provider".to_string()],
                ..Default::default()
            });
        options.identity.initial_plan.tasks[0].workspace.root = Some(source.display().to_string());
        options.identity.initial_plan.tasks[0].metadata["cook_workspace_identity"] =
            crate::agent_task_workspace_identity::attest_workspace(&source)
                .expect("attest admitted source workspace");

        let _ = run_cook(CookContext::new(options, Arc::new(UnusedExecutor)));

        let roots = roots.lock().expect("captured roots");
        let baseline = roots
            .first()
            .expect("detached dispatch received a workspace root");
        assert_ne!(
            std::path::Path::new(baseline),
            source.as_path(),
            "a dirty first attempt dispatches a controller-owned baseline"
        );
        assert!(
            std::path::Path::new(baseline).join("fixture.txt").exists(),
            "the dispatched baseline must survive dispatch_attempt returning: {baseline}"
        );
    });
}

#[test]
fn explicit_local_continuation_replaces_exhausted_auto_lab_transport_without_replaying_lab() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let config_root = homeboy_core::paths::homeboy().expect("resolve isolated config root");
        std::fs::create_dir_all(&config_root).expect("create isolated config root");
        std::fs::write(
            config_root.join("homeboy.json"),
            r#"{"retention":{"reconstructable_artifact_reserve_bytes":0}}"#,
        )
        .expect("disable host-capacity admission for local continuation");
        let (_checkout_guard, checkout) =
            homeboy_core::test_support::shared_committed_git_repo_fixture(
                "local-placement-override",
            );
        homeboy_core::test_support::run_git_fixture_command(
            &checkout,
            &[
                "remote",
                "add",
                "origin",
                checkout.to_str().expect("checkout path"),
            ],
        );
        homeboy_core::test_support::run_git_fixture_command(
            &checkout,
            &["fetch", "origin", "main"],
        );
        let worktree_parent = tempfile::tempdir().expect("create worktree parent");
        let worktree = worktree_parent.path().join("candidate");
        homeboy_core::test_support::run_git_fixture_command(
            &checkout,
            &[
                "worktree",
                "add",
                "-b",
                "local-placement-override",
                worktree.to_str().expect("worktree path"),
            ],
        );
        let lab_dispatches = Arc::new(AtomicUsize::new(0));
        let local_starts = Arc::new(AtomicUsize::new(0));
        let cook_id = "cook-local-placement-override";
        let mut options = batch_cook_options(
            cook_id,
            Arc::new(RetryableTransportFailingAttemptDispatcher {
                dispatches: Arc::clone(&lab_dispatches),
                runner_jobs_created: Arc::new(AtomicUsize::new(0)),
            }),
        );
        options.provider_transport.provider_invocation =
            Some(homeboy_core::command_invocation::CommandInvocation {
                argv: vec!["fixture-provider".to_string()],

                ..Default::default()
            });
        options.identity.initial_run_id = format!("{cook_id}-attempt-1");
        options.workspace.to_worktree = "fixture@local-placement-override".to_string();
        options.workspace.source_worktree_path = Some(worktree.clone());
        options.identity.initial_plan.tasks[0].workspace.root =
            Some(worktree.display().to_string());
        options.identity.initial_plan.tasks[0].workspace.kind =
            Some("homeboy-worktree".to_string());
        options.identity.initial_plan.tasks[0]
            .workspace
            .materialization = serde_json::json!({
            "kind": "homeboy-worktree",
            "id": options.workspace.to_worktree,
            "root": worktree,
            "branch": "local-placement-override",
        });
        homeboy_core::worktree::adopt(homeboy_core::worktree::WorktreeAdoptOptions {
            handle: options.workspace.to_worktree.clone(),
            path: worktree.display().to_string(),
            kind: Some("test-fixture".to_string()),
            provenance: None,
        })
        .expect("register original Cook worktree");
        let prior = homeboy_lab_contract::ExecutionPlacementDecision::new(
            "fixture-policy",
            "v1",
            homeboy_lab_contract::ExecutionPlacementIdentity {
                repository: "fixture".to_string(),
                workspace: "fixture-worktree".to_string(),
                task: "provider".to_string(),
                candidate: Some("candidate-a".to_string()),
                base: Some("base-a".to_string()),
            },
            homeboy_lab_contract::Placement::Auto,
            homeboy_lab_contract::ExecutionPlacementRequirement::Either,
            homeboy_lab_contract::EffectiveExecutionPlacement::Lab,
            Some(homeboy_lab_contract::ExecutionPlacementRunnerSelection {
                runner_id: "fixture-lab".to_string(),
                source: homeboy_lab_contract::RunnerSelectionSource::Policy,
            }),
            homeboy_lab_contract::ExecutionPlacementFallback {
                local_allowed: true,
                reason: Some("fixture policy allows local recovery".to_string()),
            },
            homeboy_lab_contract::ExecutionPlacementOverrideAuthorization {
                authorized: false,
                authority: None,
            },
        );
        options.identity.initial_plan.metadata["execution_placement_decision"] =
            serde_json::to_value(&prior).expect("serialize auto Lab decision");

        let exhausted = run_cook(CookContext::new(options.clone(), Arc::new(UnusedExecutor)))
            .expect("exhaust the bounded Lab transport retry");
        assert_eq!(exhausted.value.status, "pre_execution_failure");
        assert_eq!(lab_dispatches.load(Ordering::SeqCst), 2);
        let exhausted_run_id = exhausted
            .value
            .latest_run_id
            .expect("exhausted transport attempt is durable");
        let recipe_before = super::super::load_recipe(cook_id).expect("durable recipe");

        let local = homeboy_lab_contract::ExecutionPlacementDecision::new(
            prior.policy_id.clone(),
            prior.policy_revision.clone(),
            prior.identity.clone(),
            homeboy_lab_contract::Placement::Local,
            homeboy_lab_contract::ExecutionPlacementRequirement::Either,
            homeboy_lab_contract::EffectiveExecutionPlacement::Local,
            None,
            homeboy_lab_contract::ExecutionPlacementFallback {
                local_allowed: false,
                reason: None,
            },
            homeboy_lab_contract::ExecutionPlacementOverrideAuthorization {
                authorized: true,
                authority: Some("operator --placement local".to_string()),
            },
        );
        agent_task_lifecycle::transition_execution_placement_for_continuation_in_store(
            &test_lifecycle_store(),
            &exhausted_run_id,
            local.clone(),
        )
        .expect("authorize local continuation after auto Lab preacceptance failure");

        options.identity.initial_run_id = exhausted_run_id.clone();
        options.identity.initial_plan =
            agent_task_lifecycle::load_controller_plan(&exhausted_run_id)
                .expect("load transitioned plan");
        options.provider_transport.attempt_dispatcher = None;
        let continued = run_cook(CookContext::new(
            options,
            Arc::new(RecordingImmediateSuccessExecutor {
                starts: Arc::clone(&local_starts),
            }),
        ))
        .expect("local continuation starts provider work");

        assert_eq!(
            lab_dispatches.load(Ordering::SeqCst),
            2,
            "no Lab connection after override"
        );
        assert_eq!(
            local_starts.load(Ordering::SeqCst),
            1,
            "one local provider start: {continued:#?}"
        );
        assert_eq!(continued.value.cook_id, cook_id);
        let recipe_after =
            super::super::load_recipe(cook_id).expect("durable recipe after override");
        assert_eq!(
            recipe_after.promotion_transport,
            recipe_before.promotion_transport
        );
        assert_eq!(recipe_after.gate_policy, recipe_before.gate_policy);
        assert_eq!(recipe_after.retry_budget, recipe_before.retry_budget);
        assert_eq!(recipe_after.finalization, recipe_before.finalization);
        assert_eq!(
            recipe_after.attempts[0].plan.tasks[0].instructions,
            recipe_before.attempts[0].plan.tasks[0].instructions
        );
        let transitioned =
            agent_task_lifecycle::reconcile_status(&exhausted_run_id).expect("transition evidence");
        assert_eq!(
            transitioned.metadata["execution_placement_decision"]["decision_id"],
            local.decision_id
        );
        assert_eq!(
            transitioned.metadata["execution_placement_decision"]["identity"]["candidate"],
            "candidate-a"
        );
        assert_eq!(
            transitioned.metadata["transport_admission_reset"]["kind"],
            "placement_transition"
        );
    });
}

