#[derive(Default)]
struct CaptureBackend {
    body: String,
    committed: bool,
    pushed: bool,
    created: bool,
    create_count: usize,
    updated: bool,
    existing_pr: Option<AgentTaskPrRef>,
    merged_pr: Option<AgentTaskPrRef>,
    candidate_state: Option<crate::agent_task_finalization::AgentTaskPrCandidateState>,
    committed_sha: Option<String>,
    hydrate_run_id: Option<String>,
    hydrate_gate_proof_run_id: Option<String>,
    synthetic_gate_proof: Option<AgentTaskPromotionReport>,
    commit_error: bool,
    commit_real: bool,
}

impl AgentTaskPrFinalizationBackend for CaptureBackend {
    fn hydrate_run(&mut self, run_id: &str) -> Result<RunLifecycleRecord> {
        if self.hydrate_run_id.is_some() {
            return RealAgentTaskPrFinalizationBackend.hydrate_run(run_id);
        }
        Ok(RunLifecycleRecord {
            execution: RunExecutionLifecycle {
                state: RunExecutionState::Succeeded,
                started_at: None,
                finished_at: Some("2026-07-14T00:00:00Z".to_string()),
                updated_at: None,
            },
            provider_runtime: vec![ProviderRuntimeLifecycle {
                task_id: "task".to_string(),
                backend: "pi".to_string(),
                state: ProviderRuntimeState::Succeeded,
                stream_uri: None,
                external_runtime_ids: Vec::new(),
                metadata: serde_json::json!({"model": "openai/gpt-5.6-terra"}),
            }],
            ..RunLifecycleRecord::default()
        })
    }
    fn hydrate_gate_proof(&mut self, run_id: &str) -> Result<AgentTaskPrDurableGateProof> {
        if self.hydrate_run_id.is_some() || self.hydrate_gate_proof_run_id.is_some() {
            return RealAgentTaskPrFinalizationBackend.hydrate_gate_proof(run_id);
        }
        if let Some(mut promotion) = self.synthetic_gate_proof.clone() {
            promotion.source.run_id = Some(run_id.to_string());
            if let Ok(Some(persisted)) = persisted_promotion_for_attempt(run_id) {
                if let Some(follow_up) = persisted.provenance.get("cook_follow_up") {
                    promotion.provenance["cook_follow_up"] = follow_up.clone();
                }
            }
            return Ok(AgentTaskPrDurableGateProof {
                run_id: run_id.to_string(),
                promotion,
            });
        }
        Ok(AgentTaskPrDurableGateProof {
            run_id: run_id.to_string(),
            promotion: promotion(run_id),
        })
    }
    fn hydrate_run_in_store(
        &mut self,
        lifecycle_store: &AgentTaskLifecycleStore,
        run_id: &str,
    ) -> Result<RunLifecycleRecord> {
        if self.hydrate_run_id.is_some() {
            return RealAgentTaskPrFinalizationBackend
                .hydrate_run_in_store(lifecycle_store, run_id);
        }
        self.hydrate_run(run_id)
    }
    fn hydrate_gate_proof_in_store(
        &mut self,
        lifecycle_store: &AgentTaskLifecycleStore,
        run_id: &str,
    ) -> Result<AgentTaskPrDurableGateProof> {
        if self.hydrate_run_id.is_some() || self.hydrate_gate_proof_run_id.is_some() {
            return RealAgentTaskPrFinalizationBackend
                .hydrate_gate_proof_in_store(lifecycle_store, run_id);
        }
        if let Some(mut promotion) = self.synthetic_gate_proof.clone() {
            promotion.source.run_id = Some(run_id.to_string());
            if let Ok(Some(persisted)) =
                persisted_promotion_for_attempt_in_store(lifecycle_store, run_id)
            {
                if let Some(follow_up) = persisted.provenance.get("cook_follow_up") {
                    promotion.provenance["cook_follow_up"] = follow_up.clone();
                }
            }
            return Ok(AgentTaskPrDurableGateProof {
                run_id: run_id.to_string(),
                promotion,
            });
        }
        self.hydrate_gate_proof(run_id)
    }
    fn validate_candidate_in_store(
        &mut self,
        _lifecycle_store: &AgentTaskLifecycleStore,
        options: &crate::agent_task_finalization::AgentTaskPrFinalizationOptions,
    ) -> Result<()> {
        self.validate_candidate(options)
    }
    fn current_branch(&mut self, _path: &str) -> Result<String> {
        Ok("fix/8058".to_string())
    }
    fn changed_files(&mut self, _path: &str) -> Result<Vec<String>> {
        Ok(vec!["src/lib.rs".to_string()])
    }
    fn candidate_state(
        &mut self,
        _path: &str,
        _base: &crate::agent_task_finalization::AgentTaskPrResolvedBase,
        _head: &str,
    ) -> Result<crate::agent_task_finalization::AgentTaskPrCandidateState> {
        Ok(self.candidate_state.clone().unwrap_or(
            crate::agent_task_finalization::AgentTaskPrCandidateState::Dirty {
                changed_files: vec!["src/lib.rs".to_string()],
            },
        ))
    }
    fn validate_publication_identity(
        &mut self,
        _path: &str,
    ) -> Result<homeboy_core::git::GitIdentityProof> {
        Ok(homeboy_core::git::GitIdentityProof {
            host: "git.example.test".to_string(),
            name: "Homeboy Bot".to_string(),
            email: "bot@example.test".to_string(),
            committer_name: "Homeboy Bot".to_string(),
            committer_email: "bot@example.test".to_string(),
            commit_sha: None,
            scope: "repository_local".to_string(),
        })
    }
    fn validate_committed_publication_identity(
        &mut self,
        _path: &str,
        expected: Option<&homeboy_core::git::GitIdentityProof>,
    ) -> Result<homeboy_core::git::GitIdentityProof> {
        let mut proof = expected
            .cloned()
            .unwrap_or(homeboy_core::git::GitIdentityProof {
                host: "git.example.test".to_string(),
                name: "Homeboy Bot".to_string(),
                email: "bot@example.test".to_string(),
                committer_name: "Homeboy Bot".to_string(),
                committer_email: "bot@example.test".to_string(),
                commit_sha: None,
                scope: "commit_host_policy".to_string(),
            });
        proof.commit_sha = Some(
            self.committed_sha
                .clone()
                .unwrap_or_else(|| "candidate-sha".to_string()),
        );
        proof.scope = "commit_host_policy".to_string();
        Ok(proof)
    }
    fn commit_all(&mut self, path: &str, message: &str) -> Result<()> {
        if self.commit_error {
            return Err(
                homeboy_core::Error::validation_invalid_argument_with_evidence(
                    "publication",
                    "git commit failed",
                    None,
                    None,
                    Some(homeboy_error::CommandEvidence {
                        command: "git commit".to_string(),
                        cwd: None,
                        location: Some("local".to_string()),
                        exit_code: 1,
                        stdout: String::new(),
                        stderr: "hook rejected commit".to_string(),
                        truncated: false,
                    }),
                ),
            );
        }
        if self.commit_real {
            for args in [vec!["add", "."], vec!["commit", "-m", message]] {
                let output = Command::new("git")
                    .args(args)
                    .current_dir(path)
                    .output()
                    .map_err(|error| homeboy_core::Error::git_command_failed(error.to_string()))?;
                if !output.status.success() {
                    return Err(homeboy_core::Error::git_command_failed(
                        String::from_utf8_lossy(&output.stderr).to_string(),
                    ));
                }
            }
            let output = Command::new("git")
                .args(["rev-parse", "HEAD"])
                .current_dir(path)
                .output()
                .map_err(|error| homeboy_core::Error::git_command_failed(error.to_string()))?;
            self.committed_sha = Some(String::from_utf8_lossy(&output.stdout).trim().to_string());
        }
        self.committed = true;
        Ok(())
    }
    fn push_branch(
        &mut self,
        _path: &str,
        _commit_sha: &str,
        head: &str,
    ) -> Result<AgentTaskPublicationGitTracking> {
        self.pushed = true;
        Ok(AgentTaskPublicationGitTracking {
            local_branch: head.to_string(),
            remote: "origin".to_string(),
            upstream_ref: format!("refs/remotes/origin/{head}"),
            verified_remote_sha: self
                .committed_sha
                .clone()
                .unwrap_or_else(|| "candidate-sha".to_string()),
        })
    }
    fn find_open_pr(
        &mut self,
        _component_id: Option<&str>,
        _path: &str,
        _base: &str,
        _head: &str,
    ) -> Result<Option<AgentTaskPrRef>> {
        Ok(self.existing_pr.clone())
    }
    fn find_merged_pr(
        &mut self,
        _component_id: Option<&str>,
        _path: &str,
        _base: &str,
        _head: &str,
    ) -> Result<Option<AgentTaskPrRef>> {
        Ok(self.merged_pr.clone())
    }
    fn verify_remote_candidate(
        &mut self,
        _path: &str,
        _head: &str,
        candidate_sha: &str,
    ) -> Result<String> {
        Ok(candidate_sha.to_string())
    }
    fn quarantine_capability(
        &mut self,
        newly_created: bool,
        was_draft: bool,
    ) -> Result<crate::agent_task_finalization::AgentTaskPrQuarantineCapability> {
        Ok(if newly_created {
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::CloseNewPr
        } else if was_draft {
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::PreserveExistingDraft
        } else {
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::ConvertExistingReadyPrToDraft
        })
    }
    fn create_pr(
        &mut self,
        _component_id: Option<&str>,
        _path: &str,
        _base: &str,
        _head: &str,
        _title: &str,
        body: &str,
        draft: bool,
    ) -> Result<AgentTaskPrRef> {
        self.created = true;
        self.create_count += 1;
        self.body = body.to_string();
        Ok(AgentTaskPrRef {
            number: 8058,
            url: "https://github.com/Extra-Chill/homeboy/pull/8058".to_string(),
            is_draft: draft,
        })
    }
    fn update_pr(
        &mut self,
        _component_id: Option<&str>,
        _path: &str,
        number: u64,
        _title: &str,
        body: &str,
    ) -> Result<AgentTaskPrRef> {
        self.updated = true;
        self.body = body.to_string();
        Ok(AgentTaskPrRef {
            number,
            url: format!("https://github.com/Extra-Chill/homeboy/pull/{number}"),
            is_draft: self.existing_pr.as_ref().is_some_and(|pr| pr.is_draft),
        })
    }
    fn verify_publication_binding(
        &mut self,
        _path: &str,
        _base: &str,
        _head: &str,
        candidate_sha: &str,
        changed_files: &[String],
        _pr: &AgentTaskPrRef,
    ) -> Result<AgentTaskPublicationBinding> {
        Ok(AgentTaskPublicationBinding {
            candidate_sha: candidate_sha.to_string(),
            candidate_tree: match crate::agent_task_promotion::candidate_fingerprint(_path)? {
                crate::agent_task_promotion::AgentTaskPromotionCandidate::Git { fingerprint } => {
                    fingerprint.tree
                }
                crate::agent_task_promotion::AgentTaskPromotionCandidate::NonGit { .. } => {
                    "candidate-tree".to_string()
                }
            },
            remote_sha: candidate_sha.to_string(),
            pr_head_sha: candidate_sha.to_string(),
            repository: "Extra-Chill/homeboy".to_string(),
            head_repository: "Extra-Chill/homeboy".to_string(),
            changed_files: changed_files.to_vec(),
        })
    }
    fn quarantine_pr(
        &mut self,
        _path: &str,
        _pr: &AgentTaskPrRef,
        capability: crate::agent_task_finalization::AgentTaskPrQuarantineCapability,
    ) -> Result<String> {
        Ok(match capability {
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::CloseNewPr => {
                "new_pr_closed".to_string()
            }
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::PreserveExistingDraft => {
                "existing_pr_already_draft".to_string()
            }
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::ConvertExistingReadyPrToDraft => {
                "existing_pr_converted_to_draft".to_string()
            }
            crate::agent_task_finalization::AgentTaskPrQuarantineCapability::Unsupported => {
                "unsupported".to_string()
            }
        })
    }
}

/// A real, existing directory for promotion fixtures to point at.
///
/// `--path` overrides are validated for existence (`a50702c9d`), so a fixture
/// that names a literal like `/repo` now fails resolution rather than being
/// treated as opaque test data. These tests already run inside
/// `with_isolated_home`, which sets `HOME`, so materialize the directory there
/// and let every fixture share it.
fn promotion_worktree_path() -> String {
    let home = std::env::var("HOME")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|_| std::env::temp_dir());
    let path = home.join("promotion-fixture-worktree");
    std::fs::create_dir_all(&path).expect("promotion fixture worktree");
    path.display().to_string()
}

pub(crate) fn promotion(run_id: &str) -> AgentTaskPromotionReport {
    let worktree_path = promotion_worktree_path();
    serde_json::from_value(serde_json::json!({
            "schema": "homeboy/agent-task-promotion-report/v1",
            "status": "applied",
            "source": {"kind": "aggregate", "task_id": "task", "run_id": run_id},
            "to_worktree": "homeboy@8058",
            "target": {"worktree": "homeboy@8058", "path": worktree_path},
            "patch_artifact": {"id": "patch", "kind": "patch", "path": "patch", "sha256": "fixture-patch-sha"},
            "changed_files": ["src/lib.rs"],
            "deterministic_gates": [{"id": "gate", "visibility": "visible", "reveal_policy": "full_evidence", "status": "succeeded", "command": ["sh", "-c", "cargo test --locked agent_task_promotion --lib"], "exit_code": 0, "candidate_checkout": {"schema": "homeboy/agent-task-gate-candidate-checkout/v1", "commit": "candidate", "tree": "candidate-tree", "candidate_sha256": "candidate-sha"}}],
            "gate_results": [{"id": "gate", "name": "cargo test --locked agent_task_promotion --lib", "kind": "command", "status": "passed"}],
            "operator_notification": {"status": "completed", "message": "complete"},
            "verified_base": {"base": "main", "sha": "verified-base"},
            "provenance": {"worktree_path": worktree_path, "candidate_checkout": {"schema": "homeboy/agent-task-gate-candidate-checkout/v1", "commit": "candidate", "tree": "candidate-tree", "candidate_sha256": "candidate-sha"}}
        })).unwrap()
}

fn promotion_with_existing_path(run_id: &str, path: &std::path::Path) -> AgentTaskPromotionReport {
    let mut promotion = promotion(run_id);
    let path = path.display().to_string();
    promotion.target.path = Some(path.clone());
    promotion.provenance["worktree_path"] = serde_json::json!(path);
    promotion
}

#[test]
fn cook_remediation_classifies_gate_failure_without_provider_identity() {
    let options = compile_options("timeout-gate-remediation");
    let plan = options.identity.initial_plan;
    let aggregate = review_form_aggregate(&plan);
    let mut promotion = promotion("timeout-gate-remediation-run");
    promotion.status = AgentTaskPromotionStatus::GateFailed;

    assert_eq!(
        cook_remediation_same_provider(
            &promotion,
            &aggregate,
            &plan,
            None,
            &plan.tasks[0].executor,
        ),
        Some(true),
        "a failed deterministic gate is same-provider remediation even without timeout identity"
    );
    assert_eq!(
        reserve_remediation_budget(
            &crate::agent_task_scheduler::AgentTaskExecutionBudget::new(1, 1, 0),
            true,
        )
        .expect("remaining attempt is reserved")
        .same_provider_retries,
        1
    );
}

/// #15294: a provider that finished without changing anything, with no
/// terminal executor identity, must retry within the attempt budget rather
/// than stop as `policy_failure`. Homeboy's checkout proof authenticates the
/// no-change attempt the way a gate result authenticates a red candidate.
#[test]
fn cook_remediation_classifies_verified_unchanged_attempt_without_provider_identity() {
    let options = compile_options("unchanged-attempt-remediation");
    let plan = options.identity.initial_plan;
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.outcomes[0].metadata = serde_json::json!({});
    let mut promotion = promotion("unchanged-attempt-remediation-run");
    promotion.status = AgentTaskPromotionStatus::NoChanges;
    promotion.source.task_id = aggregate.outcomes[0].task_id.clone();
    promotion.changed_files.clear();
    promotion.deterministic_gates.clear();
    promotion.gate_results.clear();

    assert_eq!(
        cook_remediation_same_provider(
            &promotion,
            &aggregate,
            &plan,
            None,
            &plan.tasks[0].executor,
        ),
        None,
        "an unverified empty result keeps the identity requirement"
    );

    aggregate.outcomes[0].metadata = serde_json::json!({
        crate::agent_task::HOMEBOY_EMPTY_ATTEMPT_VERIFIED_KEY: true,
    });
    assert_eq!(
        cook_remediation_same_provider(
            &promotion,
            &aggregate,
            &plan,
            None,
            &plan.tasks[0].executor,
        ),
        Some(true),
        "a Homeboy-verified unchanged attempt is a same-provider retry"
    );

    let form: crate::agent_task_review_dossier::AiFilledReviewForm =
        serde_json::from_value(serde_json::json!({
            "pr_title": "Unable to complete the fix",
            "summary": "I read the issue, but the baseline import never ran, so I stopped without a code change.",
            "what_changed": ["Made no tracked code changes."],
            "compatibility": "No implementation changes.",
            "used_for": "Investigation only."
        }))
        .expect("review form");
    let reason = no_change_stop_reason(&promotion, &aggregate, Some(&form), 3, 3);
    assert!(
        reason.starts_with("attempt 3 of 3 produced no change"),
        "{reason}"
    );
    assert!(reason.contains("no gates ran"), "{reason}");
    assert!(
        reason.contains(
            "provider's final message: I read the issue, but the baseline import never ran"
        ),
        "{reason}"
    );
    let silent = no_change_stop_reason(&promotion, &aggregate, None, 1, 1);
    assert!(
        silent.ends_with("the provider returned no final message"),
        "{silent}"
    );
}

/// #15881: a verified no-change attempt on one rotation route hands the next
/// attempt to the following configured route instead of repeating the
/// abstaining model.
#[test]
fn no_change_follow_up_rotates_to_the_next_provider_route() {
    let options = compile_options("no-change-rotation-route");
    let mut plan = options.identity.initial_plan;
    plan.options.rotation = Some(
        crate::agent_task_scheduler::AgentTaskProviderRotationPolicy {
            entries: vec![
                crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                    model: Some("fixture-primary".to_string()),
                    ..Default::default()
                },
                crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                    model: Some("fixture-fallback".to_string()),
                    ..Default::default()
                },
            ],
            ..Default::default()
        },
    );
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.outcomes[0].metadata = serde_json::json!({
        crate::agent_task::HOMEBOY_EMPTY_ATTEMPT_VERIFIED_KEY: true,
        "provider_rotation": {
            "attempts": [{
                "attempt": 1,
                "rotation_index": 0,
                "backend": "fixture",
                "model": "fixture-primary",
                "status": "succeeded",
                "summary": null
            }]
        }
    });
    let mut promotion = promotion("no-change-rotation-route-run");
    promotion.status = AgentTaskPromotionStatus::NoChanges;
    promotion.source.task_id = aggregate.outcomes[0].task_id.clone();
    promotion.changed_files.clear();
    promotion.deterministic_gates.clear();
    promotion.gate_results.clear();

    assert!(no_change_remediation(&promotion, &aggregate));
    let (policy, entry_index) =
        no_change_rotation_route(&promotion, &plan, &aggregate, None).expect("next route");
    assert_eq!(entry_index, 1);
    assert_eq!(
        policy.entries[entry_index].model.as_deref(),
        Some("fixture-fallback")
    );

    // A chain exhausted past the terminal route keeps the existing
    // same-provider behaviour.
    let exhausted = no_change_rotation_route(
        &promotion,
        &plan_with_terminal_at_last_entry("fixture-fallback"),
        &aggregate_on_last_route(),
        None,
    );
    assert_eq!(exhausted, None, "no further route means no rotation");
}

fn plan_with_terminal_at_last_entry(fallback: &str) -> crate::agent_task_schedule::AgentTaskPlan {
    let options = compile_options("no-change-chain-exhausted");
    let mut plan = options.identity.initial_plan;
    plan.options.rotation = Some(
        crate::agent_task_scheduler::AgentTaskProviderRotationPolicy {
            entries: vec![
                crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                    model: Some(fallback.to_string()),
                    ..Default::default()
                },
            ],
            ..Default::default()
        },
    );
    plan
}

fn aggregate_on_last_route() -> crate::agent_task_scheduler::AgentTaskAggregate {
    let options = compile_options("no-change-chain-exhausted");
    let plan = options.identity.initial_plan;
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.outcomes[0].metadata = serde_json::json!({
        crate::agent_task::HOMEBOY_EMPTY_ATTEMPT_VERIFIED_KEY: true,
        "provider_rotation": {
            "attempts": [{
                "attempt": 1,
                "rotation_index": 0,
                "backend": "fixture",
                "model": "fixture-fallback",
                "status": "succeeded",
                "summary": null
            }]
        }
    });
    aggregate
}

/// #15881: a timed-out attempt is a transient failure, so its follow-up keeps
/// the existing same-provider retry instead of consuming a provider rotation.
#[test]
fn timed_out_attempt_follow_up_retries_the_same_provider_instead_of_rotating() {
    let options = compile_options("timeout-rotation-remediation");
    let mut plan = options.identity.initial_plan;
    plan.options.rotation = Some(
        crate::agent_task_scheduler::AgentTaskProviderRotationPolicy {
            entries: vec![
                crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                    model: Some("fixture-primary".to_string()),
                    ..Default::default()
                },
                crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                    model: Some("fixture-fallback".to_string()),
                    ..Default::default()
                },
            ],
            ..Default::default()
        },
    );
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.outcomes[0].metadata = serde_json::json!({
        "executor": {
            "backend": "fixture",
            "selector": null,
            "model": "fixture-primary"
        },
        "provider_rotation": {
            "attempts": [{
                "attempt": 1,
                "rotation_index": 0,
                "backend": "fixture",
                "model": "fixture-primary",
                "status": "timed_out",
                "failure_classification": "timeout",
                "summary": null
            }]
        }
    });
    aggregate.outcomes[0].failure_classification =
        Some(crate::agent_task::AgentTaskFailureClassification::Timeout);
    let mut promotion = promotion("timeout-rotation-remediation-run");
    promotion.status = AgentTaskPromotionStatus::GateFailed;
    promotion.deterministic_gates.clear();
    promotion.gate_results.clear();

    assert!(
        !no_change_remediation(&promotion, &aggregate),
        "a timed-out attempt is not a verified no-change"
    );
    assert_eq!(
        cook_remediation_same_provider(
            &promotion,
            &aggregate,
            &plan,
            None,
            &plan.tasks[0].executor,
        ),
        Some(true),
        "a timed-out route still retries itself"
    );
}

/// #15881, acceptance 2: a Cook run whose primary route was skipped as
/// unready carries the bounded skip line in its report.
#[test]
fn cook_report_surfaces_skipped_provider_routes_in_its_status_summary() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let options = compile_options("skipped-route-report");
        let run_id = "skipped-route-report-run";
        let mut plan = options.identity.initial_plan;
        plan.tasks[0].metadata = serde_json::json!({
            "provider_readiness_routing": {
                "skipped": [{
                    "backend": "fixture",
                    "selector": null,
                    "model": "anthropic/claude-sonnet-5-5",
                    "state": "credentials_unusable",
                    "reason": "PI_API_KEY is missing",
                    "reset_at": null,
                    "classification": "credentials",
                    "retryable": true,
                    "remediation": "Refresh the Roadie credential pool key, then retry.",
                    "cache_identity": null,
                    "provider_identity": null
                }]
            }
        });
        agent_task_lifecycle::submit_plan(&plan, Some(run_id)).expect("submit durable plan");
        agent_task_lifecycle::rewrite_record_for_test(run_id, |record| {
            record.metadata["provider_executions"] = serde_json::json!([{
                "task_id": plan.tasks[0].task_id,
                "attempt": 1,
                "backend": "fixture",
                "model": "openai/gpt-6-luna",
                "state": "succeeded"
            }]);
        })
        .expect("record provider execution");

        let recipe_store = super::super::cook_recipe::CookRecipeStore::from_current_data_root()
            .expect("recipe store");
        let lifecycle_store =
            AgentTaskLifecycleStore::from_current_environment().expect("lifecycle store");
        let report = cook_report_with_stores(
            Some(&recipe_store),
            Some(&lifecycle_store),
            CookReportInput {
                cook_id: "skipped-route-report".to_string(),
                status: "failed",
                disposition: CookDisposition::Terminal,
                attempts: Vec::new(),
                finalization: None,
                stop_reason: Some("attempt 1 of 1 produced no change".to_string()),
                exit_code: 1,
                invocation_latest_run_id: Some(run_id),
            },
        );
        let serialized = serde_json::to_value(&report.value).expect("report wire");
        let notes = serialized["provider_route_notes"]
            .as_array()
            .expect("notes");
        assert_eq!(notes.len(), 1, "{notes:?}");
        let note = notes[0].as_str().expect("note text");
        assert!(
            note.contains("anthropic/claude-sonnet-5-5 skipped: credentials_unusable"),
            "{note}"
        );
        assert!(
            note.contains("Refresh the Roadie credential pool key"),
            "{note}"
        );
        assert!(note.starts_with("Ran on openai/gpt-6-luna; "), "{note}");
    });
}

/// #15881: the follow-up Cook attempt an abstaining model's verified empty
/// attempt dispatches actually carries the next configured rotation route,
/// with the durable routing state advanced for the runner.
#[test]
fn verified_empty_attempt_dispatches_the_next_rotation_route() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let cook_id = "cook-15881-rotate";
        let run_id = format!("{cook_id}-attempt-1");
        let dispatches = Arc::new(AtomicUsize::new(0));
        let mut options = batch_cook_options(
            cook_id,
            Arc::new(RecordingDetachedAttemptDispatcher {
                dispatches: Arc::clone(&dispatches),
            }),
        );
        options.identity.initial_run_id = run_id.clone();
        options.retry_policy.max_attempts = 2;
        options.identity.initial_plan.options.rotation = Some(
            crate::agent_task_scheduler::AgentTaskProviderRotationPolicy {
                entries: vec![
                    crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                        model: Some("fixture-primary".to_string()),
                        ..Default::default()
                    },
                    crate::agent_task_scheduler::AgentTaskProviderRotationEntry {
                        model: Some("fixture-fallback".to_string()),
                        ..Default::default()
                    },
                ],
                ..Default::default()
            },
        );
        let mut task = options.identity.initial_plan.tasks[0].clone();
        task.policy.write = "patch".to_string();
        task.policy.apply = "manual".to_string();
        task.expected_artifacts = vec!["patch".to_string()];
        options.identity.initial_plan.tasks[0] = task.clone();
        persist_initial_recipe(&options).expect("persist Cook recipe");
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(&run_id))
            .expect("submit Cook attempt");
        agent_task_lifecycle::record_cook_attempt_in_store(
            &test_lifecycle_store(),
            cook_id,
            1,
            &run_id,
        )
        .expect("record Cook attempt");

        // Attempt 1 ran the first configured route and was proved unchanged.
        let mut aggregate = review_form_aggregate(&options.identity.initial_plan);
        aggregate.outcomes[0].metadata = serde_json::json!({
            crate::agent_task::HOMEBOY_EMPTY_ATTEMPT_VERIFIED_KEY: true,
            "provider_rotation": {
                "attempts": [{
                    "attempt": 1,
                    "rotation_index": 0,
                    "backend": "fixture",
                    "model": "fixture-primary",
                    "status": "succeeded",
                    "summary": null
                }]
            }
        });
        agent_task_lifecycle::record_run_aggregate(
            &run_id,
            &options.identity.initial_plan,
            &aggregate,
        )
        .expect("persist verified-empty aggregate");

        // The promotion fixture must be durable enough for the follow-up
        // baseline to measure: a real Git worktree whose HEAD is unchanged by
        // the (empty) promoted patch — exactly what a verified no-change
        // attempt leaves behind.
        let temp = tempfile::tempdir().expect("follow-up baseline repo");
        let repo = temp.path().join("repo");
        std::fs::create_dir(&repo).expect("create fixture repo");
        for args in [
            vec!["init"],
            vec!["config", "user.name", "Test"],
            vec!["config", "user.email", "test@example.com"],
        ] {
            assert!(Command::new("git")
                .args(args)
                .current_dir(&repo)
                .status()
                .expect("git init")
                .success());
        }
        std::fs::write(repo.join("base.txt"), "base\n").expect("base file");
        assert!(Command::new("git")
            .args(["add", "."])
            .current_dir(&repo)
            .status()
            .expect("git add")
            .success());
        assert!(Command::new("git")
            .args(["commit", "-m", "base"])
            .current_dir(&repo)
            .status()
            .expect("git commit")
            .success());
        let target_head = git_output(&repo, &["rev-parse", "HEAD"])
            .expect("fixture HEAD")
            .trim()
            .to_string();
        let patch_path = temp.path().join("empty.patch");
        std::fs::write(&patch_path, "").expect("empty patch");
        let patch_sha256 = homeboy_engine_primitives::content_hash::sha256_hex(&[]);
        let provenance_worktree = repo.display().to_string();
        let patch_display = patch_path.display().to_string();
        let finalizations = Arc::new(AtomicUsize::new(0));
        let finalize_count = Arc::clone(&finalizations);
        let side_effects = CookSideEffects::for_test(
            move |lifecycle_store, _, run_id| {
                let report: crate::agent_task_promotion::AgentTaskPromotionReport =
                    serde_json::from_value(serde_json::json!({
                        "schema": "homeboy/agent-task-promotion-report/v1",
                        "status": "no_changes",
                        "source": {"kind": "aggregate", "task_id": "provider", "run_id": run_id},
                        "to_worktree": "fixture@target",
                        "target": {"worktree": "fixture@target", "head": target_head},
                        "patch_artifact": {
                            "id": "patch",
                            "kind": "patch",
                            "path": patch_display,
                            "sha256": patch_sha256
                        },
                        "changed_files": [],
                        "deterministic_gates": [],
                        "gate_results": [],
                        "operator_notification": {"status": "completed", "message": "complete"},
                        "verified_base": {"base": "main", "sha": target_head},
                        "provenance": {"worktree_path": provenance_worktree, "candidate_commit": crate::agent_task_promotion::tests::candidate_snapshot::snapshot(std::path::Path::new(&provenance_worktree), &target_head, run_id)}
                    }))
                    .expect("no-change promotion fixture");
                lifecycle_store.record_promotion(
                    run_id,
                    serde_json::to_value(&report).expect("serialize promotion"),
                )?;
                Ok(report)
            },
            |_, _, _| unreachable!("an unchanged attempt cannot enter moving-base recovery"),
            move |_, _, _, _| {
                finalize_count.fetch_add(1, Ordering::SeqCst);
                unreachable!("an unchanged attempt must not finalize")
            },
        );
        let result = run_cook(CookContext {
            side_effects: Some(side_effects),
            ..CookContext::new(options.clone(), Arc::new(UnusedExecutor))
        });
        let report = result.expect("run_cook report");
        assert_eq!(
            report.value.status, "in_flight",
            "the detached follow-up is accepted"
        );

        assert_eq!(
            dispatches.load(Ordering::SeqCst),
            1,
            "only the no-change follow-up dispatches through the detached transport"
        );
        let recipe = load_recipe(cook_id).expect("durable recipe");
        let follow_up = recipe
            .attempts
            .iter()
            .find(|attempt| attempt.attempt == 2)
            .expect("persisted follow-up attempt");
        let follow_up_task = &follow_up.plan.tasks[0];
        assert_eq!(
            follow_up_task.executor.model(),
            Some("fixture-fallback"),
            "the follow-up runs the next configured route, not the abstaining model"
        );
        let routing = &follow_up_task.metadata["provider_readiness_routing"];
        assert_eq!(routing["next_rotation_index"], 2);
        assert_eq!(routing["provider_rotations_used"], 1);
        assert_eq!(
            follow_up_task.instructions, "complete the task",
            "the retry is still the same task"
        );
        let cook_loop = &follow_up_task.inputs["cook_loop"];
        assert_eq!(cook_loop["no_change_feedback"], true);
        assert_eq!(cook_loop["next_attempt"], 2);
        assert_eq!(cook_loop["max_attempts"], 2);
    });
}

#[test]
fn cook_remediation_preserves_provider_identity_and_no_gate_requirements() {
    let options = compile_options("provider-remediation-classification");
    let plan = options.identity.initial_plan;
    let mut aggregate = review_form_aggregate(&plan);
    aggregate.outcomes[0].metadata = serde_json::json!({
        "executor": { "backend": "fixture", "selector": null, "model": null }
    });
    let mut promotion = promotion("provider-remediation-classification-run");
    promotion.deterministic_gates.clear();
    promotion.gate_results.clear();

    assert_eq!(
        cook_remediation_same_provider(
            &promotion,
            &aggregate,
            &plan,
            None,
            &plan.tasks[0].executor,
        ),
        Some(true),
        "a normal provider failure keeps identity-based same-provider remediation"
    );

    let mut rotated = plan.tasks[0].executor.clone();
    rotated.backend = "rotated".to_string();
    assert_eq!(
        cook_remediation_same_provider(&promotion, &aggregate, &plan, None, &rotated),
        Some(false),
        "a normal provider failure can still classify provider rotation"
    );

    aggregate.outcomes[0].metadata = serde_json::json!({});
    assert_eq!(
        cook_remediation_same_provider(
            &promotion,
            &aggregate,
            &plan,
            None,
            &plan.tasks[0].executor,
        ),
        None,
        "without a gate result or terminal identity remediation stays unclassified"
    );
}

#[test]
fn canonical_completion_accepts_green_and_recipe_authorized_inherited_gate_evidence() {
    let mut green = promotion("canonical-green");
    green.patch_artifact.sha256 = Some("canonical-sha".to_string());
    assert!(canonical_finalization_eligible(&green, false, true));

    let mut inherited = green.clone();
    inherited.status = AgentTaskPromotionStatus::GateFailed;
    inherited.deterministic_gates[0].status =
        crate::agent_task_gate::AgentTaskGateStatus::AcceptedInheritedFailure;
    inherited.deterministic_gates[0].exit_code = 1;
    inherited.deterministic_gates[0].failure_evidence =
        Some(crate::agent_task_gate::AgentTaskGateFailureEvidence {
            classification:
                crate::agent_task_gate::AgentTaskGateFailureClassification::CandidateCode,
            summary: "inherited candidate failure".to_string(),
            command: "cargo test --locked agent_task_promotion --lib".to_string(),
            exit_code: 1,
            stdout_tail: String::new(),
            stderr_tail: String::new(),
            agent_feedback: String::new(),
            diagnostics: Vec::new(),
        });
    inherited.deterministic_gates[0].baseline_comparison =
        Some(crate::agent_task_gate::AgentTaskGateBaselineComparison {
            base_ref: "main".to_string(),
            exit_code: 1,
            failure_fingerprint: "inherited".to_string(),
            matches_candidate_failure: true,
            result: crate::agent_task_gate::AgentTaskGateDifferentialResult::BaselineRed,
            diagnostic: None,
        });
    assert!(canonical_finalization_eligible(&inherited, true, true));
    assert!(!canonical_finalization_eligible(&inherited, false, true));
}

#[test]
fn canonical_completion_requires_a_valid_review_form() {
    let green = promotion("canonical-missing-review-form");
    assert!(!canonical_finalization_eligible(&green, false, false));
}

#[test]
fn cook_observation_agrees_across_real_stores_without_mutation() {
    homeboy_core::test_support::with_isolated_home(|_| {
        use crate::orchestration::{LifecycleStoreLookup, OrchestrationService};
        use homeboy_control_plane_contract::{ControlPlaneRunListRequest, MissionId};
        crate::orchestration::register();

        crate::agent_task_lifecycle::activity_provider::register();
        let store = test_lifecycle_store();
        let recipes = CookRecipeStore::new(store.roots().clone());
        let mut launcher_ids = std::collections::BTreeSet::new();
        for (name, gate_status, no_finalize, receipt, success, live_owner) in [
            ("pending", "deferred", false, false, false, false),
            // A completed publication wins over an older failed-gate snapshot.
            (
                "published-after-failed-gate",
                "failed",
                false,
                true,
                true,
                false,
            ),
            ("failed", "failed", false, false, false, false),
            (
                "missing-finalization",
                "succeeded",
                false,
                false,
                false,
                false,
            ),
            ("no-finalize", "succeeded", true, false, true, false),
            ("finalized", "succeeded", false, true, true, false),
            (
                "intentional-no-change",
                "succeeded",
                false,
                false,
                true,
                false,
            ),
            ("live-verification", "deferred", false, false, false, true),
            ("live-finalization", "succeeded", false, false, false, true),
        ] {
            let mut options = compile_options(&format!("observe-{name}"));
            options.finalization.no_finalize = no_finalize;
            let mission = MissionId::new(format!("observe-mission-{name}")).unwrap();
            options.identity.initial_plan.metadata["fanout"] = serde_json::json!({
                "id": mission.as_str(), "plane": "isolated_tasks",
            });
            let run_id = &options.identity.initial_run_id;
            recipes.persist_initial_recipe(&options).unwrap();
            agent_task_lifecycle::record_completed_run(
                &options.identity.initial_plan,
                &review_form_aggregate(&options.identity.initial_plan),
                Some(run_id),
            )
            .unwrap();
            let mut proof = serde_json::to_value(promotion(run_id)).unwrap();
            proof["deterministic_gates"][0]["status"] = serde_json::json!(gate_status);
            proof["deterministic_gates"][0]["exit_code"] =
                serde_json::json!(if gate_status == "failed" { 1 } else { 0 });
            store
                .mutate_record(run_id, |record| {
                    record.metadata["cook_id"] = serde_json::json!(options.identity.cook_id);
                    crate::agent_task_service::set_cook_delivery_artifact_for_test(
                        &mut record.metadata,
                        "/promotion",
                        proof.clone(),
                    );
                    if name == "intentional-no-change" {
                        record.metadata["cook_progress"] = serde_json::json!({
                            "phase": "terminal", "terminal_status": "intentional_no_change",
                            "terminal_success": true, "exit_code": 0,
                        });
                    }
                    if live_owner {
                        let pid = std::process::id();
                        record.metadata["runner_pid"] = serde_json::json!(pid);
                        record.metadata["runner_process_start_identity"] = serde_json::json!(
                            homeboy_core::process::process_start_identity(pid).unwrap()
                        );
                    }
                    if receipt {
                        crate::agent_task_service::set_cook_delivery_artifact_for_test(
                            &mut record.metadata,
                            "/finalization",
                            serde_json::json!({
                                "status": "review_ready", "pr_url": "https://example.test/pull/42",
                            }),
                        );
                    }
                    true
                })
                .unwrap();
            store
                .record_cook_attempt(&options.identity.cook_id, 1, run_id)
                .unwrap();
            let retry_id = format!("{}-retry", options.identity.cook_id);
            submit_plan_in_test_store(&store, &options.identity.initial_plan, Some(&retry_id))
                .unwrap();
            recipes
                .record_recipe_attempt(
                    &options.identity.cook_id,
                    2,
                    &retry_id,
                    &options.identity.initial_plan,
                )
                .unwrap();
            store
                .record_cook_attempt(&options.identity.cook_id, 2, &retry_id)
                .unwrap();
            // A launcher row shares the logical Cook alias, but discovery must
            // retain that row rather than substituting the selected attempt.
            submit_plan_in_test_store(
                &store,
                &options.identity.initial_plan,
                Some(&options.identity.cook_id),
            )
            .unwrap();
            launcher_ids.insert(options.identity.cook_id.clone());
            let launcher_before = store
                .read_record_bounded(&options.identity.cook_id)
                .unwrap();
            let launcher_events_before = serde_json::to_value(
                agent_task_lifecycle::logs(&options.identity.cook_id).unwrap(),
            )
            .unwrap();
            let retry_before = store.read_record_bounded(&retry_id).unwrap();
            let before = store.read_record_bounded(run_id).unwrap();
            let recipe_before = recipes.load_recipe(&options.identity.cook_id).unwrap();
            let index_before = store.read_cook_index(&options.identity.cook_id).unwrap();
            let events_before =
                serde_json::to_value(agent_task_lifecycle::logs(run_id).unwrap()).unwrap();
            let retry_events_before =
                serde_json::to_value(agent_task_lifecycle::logs(&retry_id).unwrap()).unwrap();
            let service = OrchestrationService::new(LifecycleStoreLookup::new(store.clone()));
            // Both discovery adapters must preserve the indexed attempt identities,
            // including the queued retry that alias resolution deliberately skips.
            for filtered in [false, true] {
                let mut service_request = ControlPlaneRunListRequest {
                    mission: filtered.then(|| mission.clone()),
                    limit: 1,
                    ..Default::default()
                };
                let mut provider_request = service_request.clone();
                let mut seen = std::collections::BTreeSet::new();
                loop {
                    let page = service.runs(&service_request).unwrap();
                    let provider_page =
                        homeboy_core::control_plane::runs(&provider_request).unwrap();
                    assert_eq!(page, provider_page, "{name}: discovery adapters");
                    assert!(page.runs.len() <= 1);
                    for listed in &page.runs {
                        assert!(seen.insert(listed.run.to_string()), "duplicate attempt");
                        // List rows are summaries; only single-run reads
                        // carry action eligibility.
                        assert!(listed.action_eligibility.is_none(), "{name}: summary row");
                        let mut exact = crate::orchestration::run_exact_from_current_environment(
                            listed.run.as_str(),
                        )
                        .unwrap();
                        assert!(
                            exact.action_eligibility.take().is_some(),
                            "{name}: exact actions"
                        );
                        assert_eq!(listed, &exact, "{name}: exact row");
                        if launcher_ids.contains(listed.run.as_str()) {
                            continue;
                        }
                        let mut detail =
                            crate::agent_task_service::control_plane_run(listed.run.as_str())
                                .unwrap();
                        assert!(
                            detail.action_eligibility.take().is_some(),
                            "{name}: detail actions"
                        );
                        assert_eq!(listed, &detail, "{name}: list/detail");
                        let activity =
                            homeboy_core::activity::show_activity(listed.run.as_str()).unwrap();
                        assert_eq!(
                            listed.state
                                == homeboy_control_plane_contract::ControlPlaneRunState::Succeeded,
                            activity.items[0].state
                                == homeboy_core::activity::ActivityState::Succeeded,
                            "{name}: list/activity success"
                        );
                        assert_eq!(
                            listed.state.is_terminal(),
                            !homeboy_core::activity::is_active(activity.items[0].state)
                        );
                    }
                    assert_eq!(page.has_more, page.next_cursor.is_some());
                    let Some(cursor) = page.next_cursor else {
                        break;
                    };
                    assert_ne!(service_request.cursor.as_ref(), Some(&cursor));
                    if filtered {
                        let mismatched = ControlPlaneRunListRequest {
                            mission: Some(MissionId::new("other-mission").unwrap()),
                            cursor: Some(cursor.clone()),
                            limit: 1,
                        };
                        assert!(service.runs(&mismatched).is_err());
                        assert!(homeboy_core::control_plane::runs(&mismatched).is_err());
                    }
                    service_request.cursor = Some(cursor.clone());
                    provider_request.cursor = Some(cursor);
                }
                assert!(seen.contains(run_id));
                assert!(seen.contains(&retry_id));
                assert!(seen.contains(&options.identity.cook_id));
                if filtered {
                    assert_eq!(seen.len(), 3, "mission must exclude other Cooks");
                }
            }
            for requested in [run_id.as_str(), options.identity.cook_id.as_str()] {
                let observed = cook_observation_in_store(&store, requested).unwrap();
                let canonical = crate::agent_task_service::control_plane_run(requested).unwrap();
                let activity = homeboy_core::activity::show_activity(requested).unwrap();
                assert_eq!(observed.run_id, *run_id);
                assert_eq!(canonical.run.as_str(), run_id);
                assert_eq!(
                    observed.state() == agent_task_lifecycle::AgentTaskRunState::Succeeded,
                    success,
                    "{name}"
                );
                assert_eq!(
                    canonical.state
                        == homeboy_control_plane_contract::ControlPlaneRunState::Succeeded,
                    success,
                    "{name}"
                );
                assert_eq!(
                    activity.items[0].state == homeboy_core::activity::ActivityState::Succeeded,
                    success,
                    "{name}"
                );
                assert_eq!(
                    canonical.state.is_terminal(),
                    !homeboy_core::activity::is_active(activity.items[0].state)
                );
                if live_owner {
                    assert_eq!(
                        canonical.state,
                        homeboy_control_plane_contract::ControlPlaneRunState::Running
                    );
                    assert_eq!(
                        activity.items[0].state,
                        homeboy_core::activity::ActivityState::Running
                    );
                }
            }
            assert_eq!(store.read_record_bounded(run_id).unwrap(), before);
            assert_eq!(store.read_record_bounded(&retry_id).unwrap(), retry_before);
            assert_eq!(
                store
                    .read_record_bounded(&options.identity.cook_id)
                    .unwrap(),
                launcher_before
            );
            assert_eq!(
                serde_json::to_value(
                    agent_task_lifecycle::logs(&options.identity.cook_id).unwrap()
                )
                .unwrap(),
                launcher_events_before
            );
            assert_eq!(
                serde_json::to_value(agent_task_lifecycle::logs(&retry_id).unwrap()).unwrap(),
                retry_events_before
            );
            assert_eq!(
                cook_observation_in_store(&store, &retry_id).unwrap().run_id,
                retry_id
            );
            assert_eq!(
                recipes.load_recipe(&options.identity.cook_id).unwrap(),
                recipe_before
            );
            assert_eq!(
                serde_json::to_value(store.read_cook_index(&options.identity.cook_id).unwrap())
                    .unwrap(),
                serde_json::to_value(index_before).unwrap()
            );
            assert_eq!(
                serde_json::to_value(agent_task_lifecycle::logs(run_id).unwrap()).unwrap(),
                events_before
            );
        }
    });
}

fn tracked_promotion_continuation_options(
    cook_id: &str,
    run_id: &str,
    target: &std::path::Path,
) -> CookRequest {
    let mut options = promotion_claim_options(cook_id, run_id);
    options.identity.initial_plan =
        batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher))
            .identity
            .initial_plan;
    options.workspace.to_worktree = target.display().to_string();
    options.workspace.source_worktree_path = Some(target.to_path_buf());
    options
}

fn record_tracked_promotion_continuation(options: &CookRequest, target: &std::path::Path) {
    let recipe_store = CookRecipeStore::from_current_data_root().unwrap();
    let lifecycle_store = test_lifecycle_store();
    record_tracked_promotion_continuation_in_stores(
        &recipe_store,
        &lifecycle_store,
        options,
        target,
    );
}

fn record_tracked_promotion_continuation_in_stores(
    recipe_store: &CookRecipeStore,
    lifecycle_store: &AgentTaskLifecycleStore,
    options: &CookRequest,
    target: &std::path::Path,
) {
    if !recipe_store.recipe_exists(&options.identity.cook_id) {
        recipe_store.persist_initial_recipe(options).unwrap();
    }
    submit_plan_in_test_store(
        lifecycle_store,
        &options.identity.initial_plan,
        Some(&options.identity.initial_run_id),
    )
    .unwrap();
    lifecycle_store
        .mutate_record(&options.identity.initial_run_id, |record| {
            record.metadata["cook_id"] = serde_json::json!(options.identity.cook_id);
            record.metadata["cook_attempt"] = serde_json::json!(1);
            true
        })
        .unwrap();
    lifecycle_store
        .record_cook_attempt(
            &options.identity.cook_id,
            1,
            &options.identity.initial_run_id,
        )
        .unwrap();
    let mut checkpoint = serde_json::to_value(promotion(&options.identity.initial_run_id)).unwrap();
    checkpoint["status"] = serde_json::json!("gate_failed");
    checkpoint["deterministic_gates"][0]["status"] = serde_json::json!("failed");
    checkpoint["deterministic_gates"][0]["exit_code"] = serde_json::json!(1);
    checkpoint["gate_results"][0]["status"] = serde_json::json!("failed");
    let patch = Command::new("git")
        .args(["diff", "--binary", "--full-index"])
        .current_dir(target)
        .output()
        .expect("capture promoted patch");
    assert!(patch.status.success());
    let patch = String::from_utf8(patch.stdout).expect("patch is UTF-8");
    let patch_path = target
        .parent()
        .expect("candidate parent")
        .join("candidate.patch");
    std::fs::write(&patch_path, &patch).expect("persist patch artifact");
    let candidate =
        crate::agent_task_promotion::candidate_fingerprint(target.to_str().expect("target path"))
            .expect("candidate fingerprint");
    let crate::agent_task_promotion::AgentTaskPromotionCandidate::Git { fingerprint } = &candidate
    else {
        panic!("fixture target is a Git worktree");
    };
    let index = tempfile::NamedTempFile::new().unwrap();
    let index_path = index.path().display().to_string();
    let run_git = |args: &[&str]| {
        let output = Command::new("git")
            .args(args)
            .env("GIT_INDEX_FILE", &index_path)
            .current_dir(target)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout).unwrap().trim().to_string()
    };
    run_git(&["read-tree", "HEAD"]);
    run_git(&["add", "-A"]);
    let tree_sha = run_git(&["write-tree"]);
    let candidate_sha = run_git(&[
        "commit-tree",
        &tree_sha,
        "-p",
        &fingerprint.head,
        "-m",
        "candidate",
    ]);
    run_git(&[
        "update-ref",
        &format!(
            "refs/homeboy/candidates/{}",
            options.identity.initial_run_id
        ),
        &candidate_sha,
    ]);
    let immutable = serde_json::json!({"base_sha":fingerprint.head,"candidate_sha":candidate_sha,"tree_sha":tree_sha});
    checkpoint["to_worktree"] = serde_json::json!(options.workspace.to_worktree);
    checkpoint["target"] = serde_json::json!({
        "worktree": options.workspace.to_worktree,
        "path": target,
        "branch": "cook-candidate",
        "head": fingerprint.head
    });
    checkpoint["patch_artifact"] = serde_json::json!({
        "id": "patch",
        "kind": "patch",
        "path": patch_path,
        "sha256": format!("{:x}", sha2::Sha256::digest(patch.as_bytes())),
    });
    checkpoint["changed_files"] = serde_json::json!(fingerprint.changed_files);
    checkpoint["provenance"] = serde_json::json!({
        "post_apply": true,
        "candidate_commit": immutable,
        "candidate": candidate,
        "worktree_path": target,
        "gate_feedback_baseline": {
            "schema": "homeboy/agent-task-gate-feedback-baseline/v1",
            "current_diff": patch
        }
    });
    lifecycle_store
        .record_promotion(&options.identity.initial_run_id, checkpoint)
        .unwrap();
}

#[test]
fn fresh_cook_has_no_tracked_promotion_before_lifecycle_materialization() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let target = tempfile::tempdir().expect("tempdir");
        let options = tracked_promotion_continuation_options(
            "cook-fresh-promotion",
            "run-fresh-promotion",
            target.path(),
        );

        assert!(
            !agent_task_lifecycle::run_record_exists(&options.identity.initial_run_id).unwrap()
        );
        assert!(
            tracked_promotion_continuation_in_store(&test_lifecycle_store(), &options)
                .unwrap()
                .is_none()
        );
    });
}

#[test]
fn tracked_promotion_continuation_replays_from_the_injected_installation() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let left_context = homeboy_core::test_support::HermeticTestContext::new();
        let right_context = homeboy_core::test_support::HermeticTestContext::new();
        let left_lifecycle = AgentTaskLifecycleStore::new(left_context.path_roots());
        let right_lifecycle = AgentTaskLifecycleStore::new(right_context.path_roots());
        let left_recipe = CookRecipeStore::from_data_root(left_lifecycle.data_root());
        let target = tempfile::tempdir().expect("candidate worktree");
        for args in [
            vec!["init", "--quiet", "-b", "main"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Homeboy Test"],
        ] {
            assert!(Command::new("git")
                .args(args)
                .current_dir(target.path())
                .status()
                .unwrap()
                .success());
        }
        std::fs::write(target.path().join("tracked.txt"), "base\n").unwrap();
        assert!(Command::new("git")
            .args(["add", "."])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["commit", "--quiet", "-m", "base"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["checkout", "--quiet", "-b", "cook-candidate"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        std::fs::write(target.path().join("tracked.txt"), "promoted\n").unwrap();
        let options = tracked_promotion_continuation_options(
            "cook-injected-continuation",
            "run-injected-continuation",
            target.path(),
        );
        record_tracked_promotion_continuation_in_stores(
            &left_recipe,
            &left_lifecycle,
            &options,
            target.path(),
        );

        let first = tracked_promotion_continuation_in_store(&left_lifecycle, &options)
            .unwrap()
            .expect("left installation owns the promotion");
        let replay = tracked_promotion_continuation_in_store(&left_lifecycle, &options)
            .unwrap()
            .expect("left installation replays deterministically");
        assert_eq!(first.path, replay.path);
        assert!(
            tracked_promotion_continuation_in_store(&right_lifecycle, &options)
                .unwrap()
                .is_none()
        );
    });
}

#[test]
fn terminal_persisted_promotion_loads_without_source_aggregate() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let run_id = "run-persisted-promotion-without-aggregate";
        let options = promotion_claim_options("cook-persisted-promotion", run_id);
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id)).unwrap();
        let expected = promotion(run_id);
        agent_task_lifecycle::record_promotion(
            run_id,
            serde_json::to_value(&expected).expect("serialize promotion fixture"),
        )
        .unwrap();
        let lifecycle_store = test_lifecycle_store();
        assert!(lifecycle_store.read_aggregate(run_id).is_err());

        let preflight = preflight_cook_promotion_in_store(
            &lifecycle_store,
            &options,
            run_id,
            Some("different-artifact"),
        )
        .expect("terminal persisted promotion is authoritative");
        assert_eq!(preflight["behavior"], "load_persisted");
        assert_eq!(preflight["artifact_id"], "patch");
        let loaded = promote_or_load_attempt_in_store(&lifecycle_store, &options, run_id)
            .expect("execution loads terminal persisted promotion");
        assert_eq!(loaded.status, AgentTaskPromotionStatus::Applied);
        assert_eq!(loaded.source.run_id.as_deref(), Some(run_id));
        assert_eq!(loaded.patch_artifact.id, expected.patch_artifact.id);

        let mut pending = promotion(run_id);
        pending.status = AgentTaskPromotionStatus::VerificationPending;
        let pending = serde_json::to_value(pending).expect("serialize pending fixture");
        agent_task_lifecycle::rewrite_record_for_test(run_id, |record| {
            crate::agent_task_service::set_cook_delivery_artifact_for_test(
                &mut record.metadata,
                "/promotion",
                pending.clone(),
            );
        })
        .unwrap();
        assert!(
            preflight_cook_promotion_in_store(&lifecycle_store, &options, run_id, None).is_err()
        );
        assert!(promote_or_load_attempt_in_store(&lifecycle_store, &options, run_id).is_err());
    });
}

#[test]
fn production_cook_loop_loads_terminal_promotion_without_source_aggregate() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let cook_id = "cook-loop-persisted-promotion";
        let run_id = "run-loop-persisted-promotion";
        let mut options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
        let expected = promotion(run_id);
        options.identity.initial_run_id = run_id.to_string();
        options.provider_transport.attempt_dispatcher = None;
        options.workspace.to_worktree = expected.target.worktree.clone();
        homeboy_core::worktree::adopt(homeboy_core::worktree::WorktreeAdoptOptions {
            handle: expected.target.worktree.clone(),
            path: expected.target.path.clone().expect("promotion target path"),
            kind: Some("test-fixture".to_string()),
            provenance: None,
        })
        .expect("register persisted promotion target");
        super::super::persist_initial_recipe(&options).expect("persist Cook recipe");
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id))
            .expect("persist terminal attempt");
        agent_task_lifecycle::record_cook_attempt_in_store(
            &test_lifecycle_store(),
            cook_id,
            1,
            run_id,
        )
        .expect("index terminal attempt");
        agent_task_lifecycle::rewrite_record_for_test(run_id, |record| {
            record.set_state_for_test(agent_task_lifecycle::AgentTaskRunState::Succeeded);
        })
        .expect("terminalize fixture");
        agent_task_lifecycle::record_promotion(
            run_id,
            serde_json::to_value(expected).expect("serialize promotion fixture"),
        )
        .expect("persist terminal promotion");

        let store = CookRecipeStore::from_current_data_root().expect("recipe store");
        let lifecycle_store = test_lifecycle_store();
        assert!(lifecycle_store.read_aggregate(run_id).is_err());
        let result = CookService::run(
            options,
            CookRuntime::production(Arc::new(UnusedExecutor), &store, &lifecycle_store),
            CookMode::Resume,
        )
        .expect("production Cook loop loads persisted promotion");

        assert_eq!(result.exit_code, 0, "{result:#?}");
        assert_eq!(result.value.status, "green_no_finalize");
        assert_eq!(result.value.attempts.len(), 1);
        assert_eq!(
            result.value.attempts[0]
                .promotion
                .as_ref()
                .expect("persisted promotion reported")
                .status,
            AgentTaskPromotionStatus::Applied
        );
        assert!(lifecycle_store.read_aggregate(run_id).is_err());
    });
}

