#[test]
fn cook_owned_unpushed_candidate_requires_one_exact_promoted_commit() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let target = tempfile::tempdir().expect("target");
        for args in [
            vec!["init", "--quiet", "-b", "main"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Homeboy Test"],
        ] {
            assert!(Command::new("git")
                .args(args)
                .current_dir(target.path())
                .status()
                .unwrap()
                .success());
        }
        std::fs::write(target.path().join("tracked.txt"), "base\n").unwrap();
        assert!(Command::new("git")
            .args(["add", "tracked.txt"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["commit", "--quiet", "-m", "base"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["checkout", "--quiet", "-b", "cook-candidate"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        std::fs::write(target.path().join("tracked.txt"), "promoted\n").unwrap();
        let options = tracked_promotion_continuation_options(
            "cook-owned-unpushed",
            "run-cook-owned-unpushed",
            target.path(),
        );
        record_tracked_promotion_continuation(&options, target.path());
        assert!(Command::new("git")
            .args(["add", "tracked.txt"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["commit", "--quiet", "-m", "cook: retain candidate"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        let continuation =
            tracked_promotion_continuation_in_store(&test_lifecycle_store(), &options)
                .unwrap()
                .expect("durable Cook attribution");
        assert!(cook_owned_unpushed_destination(&continuation).unwrap());

        let base = Command::new("git")
            .args(["rev-parse", "HEAD^"])
            .current_dir(target.path())
            .output()
            .unwrap();
        let base = String::from_utf8(base.stdout).unwrap().trim().to_string();
        assert!(Command::new("git")
            .args(["branch", "side", &base])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["checkout", "--quiet", "side"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        std::fs::write(target.path().join("side.txt"), "side\n").unwrap();
        assert!(Command::new("git")
            .args(["add", "side.txt"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["commit", "--quiet", "-m", "side"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["checkout", "--quiet", "cook-candidate"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        assert!(Command::new("git")
            .args(["merge", "--quiet", "--no-ff", "-s", "ours", "side", "-m", "merge"])
            .current_dir(target.path())
            .status()
            .unwrap()
            .success());
        let error = cook_owned_unpushed_destination(&continuation).unwrap_err();
        assert_eq!(
            error.details["workspace"]["classification"],
            "workspace.cook_owned_unpushed_commit_mismatch"
        );
        assert_eq!(error.details["workspace"]["reason"], "merge_commit");
    });
}

/// Performs only the replacement-gate and publication steps, through their
/// default service handlers; every other step is a test failure.
struct ReplacementOnlyRecoveryPerformer;

impl crate::agent_task_service::CookRecoveryPerformer for ReplacementOnlyRecoveryPerformer {
    fn continue_cook(
        &self,
        run_id: &str,
        _rearm: bool,
        _overrides: &crate::agent_task_service::CookRecoveryOverrides,
    ) -> Result<(serde_json::Value, i32)> {
        panic!("replacement recovery must not continue {run_id}")
    }

    fn preflight_continue_cook(
        &self,
        run_id: &str,
        _rearm: bool,
    ) -> Result<(serde_json::Value, i32)> {
        panic!("replacement recovery must not preflight continuation of {run_id}")
    }

    fn retry(&self, run_id: &str) -> Result<(serde_json::Value, i32)> {
        panic!("replacement recovery must not retry {run_id}")
    }

    fn reconcile(&self, run_id: &str) -> Result<(serde_json::Value, i32)> {
        panic!("replacement recovery must not reconcile {run_id}")
    }

    fn adopt(&self, run_id: &str, candidate_ref: &str) -> Result<(serde_json::Value, i32)> {
        panic!("replacement recovery must not adopt {candidate_ref} into {run_id}")
    }
}

#[test]
fn verify_replacement_gates_recovers_pending_verification_and_replays_completed_proof() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let temp = tempfile::tempdir().expect("tempdir");
        let source = temp.path().join("source");
        let target = temp.path().join("candidate");
        std::fs::create_dir(&source).expect("create source");
        for args in [
            vec!["init", "--quiet", "-b", "main"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Homeboy Test"],
        ] {
            assert!(Command::new("git")
                .args(args)
                .current_dir(&source)
                .status()
                .expect("run git")
                .success());
        }
        std::fs::create_dir_all(source.join("figma-transformer"))
            .expect("create changed component");
        std::fs::create_dir_all(source.join("php-transformer")).expect("create gate component");
        std::fs::write(source.join("figma-transformer/tracked.txt"), "base\n").expect("write base");
        std::fs::write(source.join("php-transformer/gate.txt"), "gate\n")
            .expect("write gate component");
        assert!(Command::new("git")
            .args(["add", "."])
            .current_dir(&source)
            .status()
            .expect("stage base")
            .success());
        assert!(Command::new("git")
            .args(["commit", "--quiet", "-m", "base"])
            .current_dir(&source)
            .status()
            .expect("commit base")
            .success());
        assert!(Command::new("git")
            .args(["worktree", "add", "--quiet", "-b", "cook-candidate"])
            .arg(&target)
            .current_dir(&source)
            .status()
            .expect("create candidate")
            .success());
        std::fs::write(target.join("figma-transformer/tracked.txt"), "promoted\n")
            .expect("write candidate");

        let mut options = batch_cook_options(
            "cook-verify-replacement",
            Arc::new(AcceptedDetachedAttemptDispatcher),
        );
        options.identity.initial_run_id = "run-verify-replacement".to_string();
        options.workspace.to_worktree = "fixture@cook-candidate".to_string();
        options.workspace.source_worktree_path = Some(target.clone());
        options.gates.accept_inherited_failures = true;
        persist_initial_recipe(&options).expect("persist recipe");
        record_tracked_promotion_continuation(&options, &target);
        agent_task_lifecycle::record_cook_attempt_in_store(
            &test_lifecycle_store(),
            "cook-verify-replacement",
            1,
            "run-verify-replacement",
        )
        .expect("link attempt");

        let patch_path = target
            .parent()
            .expect("candidate parent")
            .join("candidate.patch");
        seed_candidate_commit_aggregate(
            "run-verify-replacement",
            &options.identity.initial_plan,
            &patch_path.with_extension("repo"),
        );
        let mut failed = serde_json::to_value(
            persisted_promotion_for_attempt("run-verify-replacement")
                .expect("read failed promotion")
                .expect("failed promotion"),
        )
        .expect("serialize failed promotion");
        failed["source"]["task_id"] =
            serde_json::json!(options.identity.initial_plan.tasks[0].task_id.clone());
        failed["status"] = serde_json::json!("verification_pending");
        failed["patch_artifact"]["id"] = serde_json::json!("committed-changes");
        failed["verified_base"]["sha"] =
            serde_json::json!(
                git_output(&source, &["rev-parse", "HEAD"]).expect("resolve fixture base")
            );
        failed["target"]["dirty"] = serde_json::json!(true);
        agent_task_lifecycle::record_promotion("run-verify-replacement", failed)
            .expect("align source task evidence");

        agent_task_lifecycle::rewrite_record_for_test("run-verify-replacement", |record| {
            let cwd = serde_json::json!({
                "requested": target,
                "effective": target.join("php-transformer"),
            });
            crate::agent_task_service::set_cook_delivery_artifact_for_test(
                &mut record.metadata,
                "/promotion/deterministic_gates/0/cwd",
                cwd.clone(),
            );
            let history = record.metadata["cook_delivery"]["artifacts"]["promotions"]
                .as_array_mut()
                .expect("promotion history");
            history.last_mut().expect("failed promotion history")["deterministic_gates"][0]
                ["cwd"] = cwd;
        })
        .expect("persist sibling gate cwd");

        let gate_log = temp.path().join("replacement-gate-runs");
        let gate = format!(
            "printf ran >> {}; printf inherited >&2; exit 1",
            gate_log.display()
        );
        let reviewer_gate = "test \"$(cat \"$(git rev-parse --show-toplevel)/figma-transformer/tracked.txt\")\" = promoted".to_string();
        let candidate_ref = "refs/homeboy/candidates/run-verify-replacement";
        let candidate_sha = git_output(&target, &["rev-parse", candidate_ref]).unwrap();
        git_output(&target, &["update-ref", "-d", candidate_ref]).unwrap();
        verify_replacement_gates(
            "cook-verify-replacement",
            VerifyGateOptions {
                verify: vec![reviewer_gate.clone()],
                accept_inherited_failures: true,
                ..Default::default()
            },
            "Chris approved corrected gate evidence".to_string(),
            None,
        )
        .expect_err("missing candidate ref fails before shell execution");
        assert!(!replacement_gate_execution_started(
            &test_lifecycle_store(),
            "run-verify-replacement"
        )
        .expect("read replacement gate fence"));
        git_output(&target, &["update-ref", candidate_ref, &candidate_sha]).unwrap();
        std::fs::remove_file(&patch_path).expect("patch evidence is not a continuation input");
        mark_replacement_gate_execution_started(&test_lifecycle_store(), "run-verify-replacement")
            .expect("persist interrupted replacement execution");
        agent_task_lifecycle::rewrite_record_for_test("run-verify-replacement", |record| {
            record.metadata["replacement_gate_execution_fences"]["verify-replacement"]
                ["owner_pid"] = serde_json::json!(u32::MAX);
        })
        .expect("simulate terminated interrupted executor");
        let interrupted = verify_replacement_gates(
            "cook-verify-replacement",
            VerifyGateOptions {
                verify: vec![reviewer_gate.clone()],
                ..Default::default()
            },
            "Chris approved corrected gate evidence".to_string(),
            None,
        )
        .expect_err("interrupted gates require explicit rerun authority");
        assert_eq!(
            interrupted.details["recovery"]["kind"],
            "external_candidate_bound_proof_required"
        );
        assert!(!gate_log.exists());
        // The corrected gates reach the candidate through `agent-task recover`,
        // which resolves the Cook ID to the attempt `status` reports (#15886).
        let replace_gates = crate::agent_task_service::CookReplaceGatesRequest {
            proof: crate::agent_task_service::CookReplacementProof::Gates(VerifyGateOptions {
                verify: vec![reviewer_gate.clone()],
                private_verify: vec![gate.clone()],
                execution_policy: crate::agent_task_gate::AgentTaskGateExecutionPolicy::ContinueAll,
                accept_inherited_failures: true,
                ..Default::default()
            }),
            authorize_external_proof: "Chris approved corrected gate evidence".to_string(),
            authorize_interrupted_rerun: Some(
                "Chris approved rerunning after the interrupted executor".to_string(),
            ),
        };
        let (preflight, preflight_exit_code) = crate::agent_task_service::recover_cook(
            "cook-verify-replacement",
            crate::agent_task_service::CookRecoveryRequest {
                preflight: true,
                replace_gates: Some(replace_gates.clone()),
                ..Default::default()
            },
            &ReplacementOnlyRecoveryPerformer,
        )
        .expect("recover --preflight names replacement gates");
        assert_eq!(preflight_exit_code, 0);
        assert_eq!(preflight.run_id, "run-verify-replacement");
        assert_eq!(
            preflight.step,
            crate::agent_task_service::CookRecoveryStep::ReplaceGates
        );
        assert!(preflight.result.is_none());
        assert!(!gate_log.exists(), "preflight executes no gate");
        let (recovered, recovered_exit_code) = crate::agent_task_service::recover_cook(
            "cook-verify-replacement",
            crate::agent_task_service::CookRecoveryRequest {
                replace_gates: Some(replace_gates),
                ..Default::default()
            },
            &ReplacementOnlyRecoveryPerformer,
        )
        .expect("recover performs replacement gates");
        assert_eq!(recovered_exit_code, 0);
        assert_eq!(
            recovered.step,
            crate::agent_task_service::CookRecoveryStep::ReplaceGates
        );
        let mut result = recovered.result.expect("replacement proof");
        let handoff = result
            .as_object_mut()
            .and_then(|object| object.remove("handoff"))
            .expect("replacement handoff");
        assert_eq!(
            handoff["next_command"],
            "homeboy agent-task recover run-verify-replacement"
        );
        let replacement: AgentTaskPromotionReport =
            serde_json::from_value(result).expect("typed replacement proof");

        assert_eq!(replacement.status, AgentTaskPromotionStatus::GateFailed);
        assert_eq!(replacement.patch_artifact.id, candidate_sha);
        assert!(replacement.deterministic_gates.iter().all(|gate| gate
            .candidate_checkout
            .as_ref()
            .is_none_or(|checkout| checkout.commit == candidate_sha)));
        assert_eq!(
            replacement.provenance["candidate"]["fingerprint"]["target_path"],
            serde_json::json!(std::fs::canonicalize(&target)
                .expect("canonical candidate root")
                .display()
                .to_string())
        );
        assert_eq!(
            replacement.changed_files,
            vec!["figma-transformer/tracked.txt"]
        );
        assert_eq!(
            replacement.deterministic_gates[1]
                .cwd
                .as_ref()
                .expect("gate cwd evidence")
                .effective,
            target.join("php-transformer").display().to_string()
        );
        assert_eq!(replacement.deterministic_gates.len(), 2);
        assert_eq!(
            replacement.deterministic_gates[0].command,
            crate::agent_task_gate::legacy_gate_argv(&reviewer_gate)
        );
        assert_eq!(
            replacement.deterministic_gates[1].command,
            crate::agent_task_gate::legacy_gate_argv(&gate)
        );
        assert_eq!(
            replacement.deterministic_gates[1].visibility,
            homeboy_core::gate::HomeboyGateVisibility::Private,
            "a private required gate remains durable runtime evidence"
        );
        assert_eq!(
            replacement.deterministic_gates[1].status,
            crate::agent_task_gate::AgentTaskGateStatus::AcceptedInheritedFailure
        );
        let error = verify_replacement_gates(
            "cook-verify-replacement",
            VerifyGateOptions {
                verify: vec![replacement.deterministic_gates[0].command[2].clone()],
                ..Default::default()
            },
            "Chris approved corrected gate evidence".to_string(),
            None,
        )
        .expect_err("completed inherited failure needs renewed authorization");
        assert_eq!(error.details["field"], "accept_inherited_failures");
        let replay = verify_replacement_gates(
            "cook-verify-replacement",
            VerifyGateOptions {
                verify: vec![replacement.deterministic_gates[0].command[2].clone()],
                accept_inherited_failures: true,
                ..Default::default()
            },
            "Chris approved corrected gate evidence".to_string(),
            None,
        )
        .expect("completed replacement proof replays without rerunning gates");
        assert_eq!(replay.status, replacement.status);
        assert_eq!(replay.command_evidence, replacement.command_evidence);
        assert_eq!(
            std::fs::read_to_string(gate_log).expect("read gate log"),
            "ranran"
        );
        let record =
            agent_task_lifecycle::reconcile_status("run-verify-replacement").expect("read record");
        assert_eq!(
            record.metadata["cook_delivery"]["artifacts"]["promotions"]
                .as_array()
                .unwrap()
                .len(),
            3
        );
        assert_eq!(
            agent_task_lifecycle::operation_claim(
                "run-verify-replacement",
                "verify-replacement:run-verify-replacement"
            )
            .expect("read replacement claim")
            .expect("replacement claim")
            .state,
            agent_task_lifecycle::ClaimState::Completed
        );
        assert_eq!(
            record.metadata["cook_delivery"]["artifacts"]["promotion"]["provenance"]
                ["replacement_gate_proof"]["original_history"]["status"],
            "verification_pending"
        );
        assert_eq!(
            record.metadata["cook_delivery"]["artifacts"]["promotion"]["provenance"]
                ["replacement_gate_proof"]["reason"],
            "interrupted_original_verification"
        );
        assert_eq!(
            record.metadata["cook_delivery"]["artifacts"]["promotion"]["provenance"]
                ["replacement_gate_proof"]["accept_inherited_failures"],
            true
        );
        assert_eq!(
            record.metadata["cook_delivery"]["artifacts"]["promotion"]["provenance"]
                ["replacement_gate_execution_recovery"]["operator_authorization"],
            "Chris approved rerunning after the interrupted executor"
        );
    });
}

#[path = "cook_tests/candidate_continuation.rs"]
mod candidate_continuation;

fn with_corrected_gate_candidate(
    test: impl FnOnce(CookRequest, PathBuf, AgentTaskPromotionReport),
) {
    with_corrected_gate_candidate_placement(false, test);
}

fn with_corrected_gate_candidate_placement(
    lab: bool,
    test: impl FnOnce(CookRequest, PathBuf, AgentTaskPromotionReport),
) {
    homeboy_core::test_support::with_isolated_home(|_| {
        let temp = tempfile::tempdir().unwrap();
        let target = temp.path().join("candidate");
        std::fs::create_dir(&target).unwrap();
        for args in [
            vec!["init", "--quiet", "-b", "main"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Homeboy Test"],
        ] {
            assert!(Command::new("git")
                .args(args)
                .current_dir(&target)
                .status()
                .unwrap()
                .success());
        }
        std::fs::write(target.join("Cargo.toml"), "[package]\nname = \"corrected-gate-fixture\"\nversion = \"0.1.0\"\nedition = \"2021\"\n[lib]\npath = \"lib.rs\"\n").unwrap();
        std::fs::write(target.join(".gitignore"), "target/\nCargo.lock\n").unwrap();
        std::fs::write(target.join("lib.rs"), "#[cfg(test)] mod tests { #[test] fn provider_one() {} #[test] fn provider_two() {} }\n").unwrap();
        std::fs::write(target.join("tracked.txt"), "base\n").unwrap();
        for args in [
            vec!["add", "."],
            vec!["commit", "--quiet", "-m", "base"],
            vec!["checkout", "--quiet", "-b", "fix/8058"],
        ] {
            assert!(Command::new("git")
                .args(args)
                .current_dir(&target)
                .status()
                .unwrap()
                .success());
        }
        let invalid = "cargo test -p corrected-gate-fixture missing_provider";
        assert!(Command::new("git")
            .args(["remote", "add", "origin"])
            .arg(&target)
            .current_dir(&target)
            .status()
            .unwrap()
            .success());
        let invalid_gate = crate::agent_task_gate::run_gate_command(&target, 0, invalid).unwrap();
        assert_eq!(
            invalid_gate
                .failure_evidence
                .as_ref()
                .unwrap()
                .classification,
            crate::agent_task_gate::AgentTaskGateFailureClassification::ZeroTestsSelected
        );
        std::fs::write(target.join("tracked.txt"), "promoted\n").unwrap();
        let mut options = batch_cook_options(
            "cook-corrected-gate",
            Arc::new(AcceptedDetachedAttemptDispatcher),
        );
        options.identity.initial_run_id = "run-corrected-gate".to_string();
        options.ai_disclosure.ai_model = Some("openai/gpt-6.1-sol".to_string());
        options.identity.initial_plan.tasks[0].executor.model =
            Some("openai/gpt-6.1-sol".to_string());
        options.workspace.to_worktree = "fixture@fix-8058".to_string();
        options.workspace.source_worktree_path = Some(target.clone());
        options.finalization.head = Some("fix/8058".to_string());
        options.finalization.no_finalize = false;
        options.gates.verify = vec![invalid.to_string()];
        persist_initial_recipe(&options).unwrap();
        record_tracked_promotion_continuation(&options, &target);
        let run_id = &options.identity.initial_run_id;
        let patch_path = temp.path().join("candidate.patch");
        seed_candidate_commit_aggregate(
            run_id,
            &options.identity.initial_plan,
            &patch_path.with_extension("repo"),
        );
        let store = test_lifecycle_store();
        let mut aggregate = store.read_aggregate(run_id).unwrap();
        aggregate.status = AgentTaskAggregateStatus::CandidateRecoverable;
        aggregate.totals.succeeded = 0;
        aggregate.totals.recoverable_candidates = 1;
        aggregate.outcomes[0].status =
            crate::agent_task::AgentTaskOutcomeStatus::CandidateRecoverable;
        let checkpoint = persisted_promotion_for_attempt(run_id).unwrap().unwrap();
        aggregate.outcomes[0].candidate = Some(
            serde_json::from_value(checkpoint.provenance["candidate_commit"].clone()).unwrap(),
        );
        aggregate.outcomes[0].artifacts.clear();
        std::fs::remove_file(&patch_path).unwrap();
        store
            .record_run_aggregate(run_id, &options.identity.initial_plan, &aggregate)
            .unwrap();
        agent_task_lifecycle::rewrite_record_for_test(run_id, |record| {
            record.lifecycle.provider_runtime = vec![ProviderRuntimeLifecycle {
                task_id: options.identity.initial_plan.tasks[0].task_id.clone(),
                backend: "pi".to_string(), state: ProviderRuntimeState::Failed,
                stream_uri: None, external_runtime_ids: Vec::new(),
                metadata: serde_json::json!({"model": "openai/gpt-6.1-sol", "evidence_source": "durable_provider_execution"}),
            }];
        }).unwrap();
        let mut failed = persisted_promotion_for_attempt(run_id).unwrap().unwrap();
        failed.source.task_id = options.identity.initial_plan.tasks[0].task_id.clone();
        failed.verified_base.as_mut().unwrap().sha =
            git_output(&target, &["rev-parse", "HEAD"]).unwrap();
        failed.deterministic_gates = vec![invalid_gate];
        failed.normalize_gate_outcome();
        store
            .record_promotion(run_id, serde_json::to_value(&failed).unwrap())
            .unwrap();
        if lab {
            let recipe_store = CookRecipeStore::from_current_data_root().unwrap();
            let mut recipe = recipe_store.load_recipe(&options.identity.cook_id).unwrap();
            recipe.promotion_transport["attempt_dispatch"] = serde_json::json!({
                "kind": "lab", "runner_id": "replacement-placement-runner"
            });
            recipe_store.persist_recipe(&recipe).unwrap();
            let mut config = homeboy_core::defaults::load_config();
            config.retention.shared_store_reserve_bytes = u64::MAX;
            homeboy_core::defaults::save_config(&config).unwrap();
        }
        let replacement = verify_replacement_gates(
            run_id,
            VerifyGateOptions {
                verify: vec!["test \"$(cat tracked.txt)\" = promoted".to_string()],
                gate_environment: crate::agent_task_gate::AgentTaskGateEnvironmentPolicy {
                    shared_cargo_target: Some(lab),
                    ..Default::default()
                },
                ..Default::default()
            },
            "operator authorized corrected candidate-bound gates".to_string(),
            None,
        )
        .unwrap();
        assert_eq!(replacement.status, AgentTaskPromotionStatus::Applied);
        test(options, target, replacement);
    });
}

#[test]
fn replacement_gates_follow_lab_placement_without_controller_reserve_preflight() {
    use crate::agent_task_gate::placement;
    struct RunnerTransport {
        previous: Arc<dyn placement::LabGateTransport>,
        requests: Arc<std::sync::Mutex<Vec<placement::LabGateRequest>>>,
    }
    impl placement::LabGateTransport for RunnerTransport {
        fn declared_runner(&self, command: &str) -> Result<Option<String>> {
            self.previous.declared_runner(command)
        }
        fn execute(
            &self,
            cwd: &std::path::Path,
            request: &placement::LabGateRequest,
            supervision: Option<&crate::agent_task_gate::GateSupervision>,
        ) -> Result<placement::LabGateReceipt> {
            if request.runner_id != "replacement-placement-runner" {
                return self.previous.execute(cwd, request, supervision);
            }
            self.requests.lock().unwrap().push(request.clone());
            // Simulate the runner's independent environment. The controller's
            // deliberately impossible reserve must never be admitted locally.
            let mut environment = request.environment.clone();
            environment.lab_runner = None;
            environment.shared_cargo_target = Some(false);
            let mut report = crate::agent_task_gate::run_gate_command_with_supervision(
                cwd,
                request.index,
                if request.preflight_only {
                    "true"
                } else {
                    &request.label
                },
                request.visibility,
                request.reveal_policy,
                None,
                supervision,
                &environment,
                &[],
            )?;
            report.environment.lab_runner = Some(request.runner_id.clone());
            if request.preflight_only {
                report.status = crate::agent_task_gate::AgentTaskGateStatus::Skipped;
            }
            Ok(placement::LabGateReceipt {
                schema: placement::LAB_GATE_RECEIPT_SCHEMA.to_string(),
                request_sha256: request.identity()?,
                candidate: request.candidate.clone(),
                execution_context: homeboy_core::runner_job_execution_context::RunnerJobExecutionContext::direct_daemon(
                    Some("controller-run"), &request.runner_id, "job", "homeboy", "reservation",
                )?.evidence_record()?,
                report, setup: vec![], readiness: request.preflight_only.then(|| serde_json::json!({"status":"ready"})), materialization: None, artifact_ref: None,
            })
        }
    }
    let requests = Arc::new(std::sync::Mutex::new(Vec::new()));
    placement::register_lab_gate_transport(Arc::new(RunnerTransport {
        previous: placement::active_transport(),
        requests: requests.clone(),
    }));
    with_corrected_gate_candidate_placement(true, |_, _, replacement| {
        let requests = requests.lock().unwrap();
        assert!(!requests.is_empty());
        assert!(requests
            .iter()
            .all(|request| request.runner_id == "replacement-placement-runner"));
        let proof = &replacement.provenance["replacement_gate_proof"]["environment_policy"][0];
        assert_eq!(proof["runner_id"], "replacement-placement-runner");
        assert_eq!(
            proof["lab_receipt"]["execution_context"]["context"]["runner_id"],
            "replacement-placement-runner"
        );
        assert!(replacement.deterministic_gates[0].lab_receipt.is_some());
    });
}

