/// #15364: the dependency tool preflight is a no-op when there is nothing to
/// hydrate, so admission never regresses for repositories without lockfiles.
#[test]
fn dependency_tool_preflight_is_a_noop_without_dependencies() {
    homeboy_core::test_support::with_isolated_home(|_home| {
        let mut options = compile_options("dependency-tool-preflight");
        assert!(super::dependency_tool_preflight_error(&options)
            .expect("no workspace")
            .is_none());

        let workspace = tempfile::tempdir().expect("workspace");
        std::fs::write(workspace.path().join("README.md"), "no dependencies\n")
            .expect("plain file");
        options.workspace.source_worktree_path = Some(workspace.path().to_path_buf());
        assert!(super::dependency_tool_preflight_error(&options)
            .expect("plain workspace")
            .is_none());

        options.workspace.source_worktree_path = Some(workspace.path().join("missing"));
        assert!(super::dependency_tool_preflight_error(&options)
            .expect("absent workspace")
            .is_none());
    });
}

/// #15364: a gate setup failure during promotion is environmental, so Cook
/// retries promotion automatically instead of stranding the durable candidate
/// until an operator runs `agent-task recover`. Other promotion errors are final.
#[test]
fn gate_setup_failures_are_retried_and_other_promotion_errors_are_not() {
    let context = homeboy_core::test_support::HermeticTestContext::new();
    let lifecycle_store = AgentTaskLifecycleStore::new(context.path_roots());
    let options = compile_options("gate-setup-retry");
    let setup_failure = || {
        homeboy_core::Error::dependency_step_failed(
            "promotion.gate_setup",
            "pnpm",
            Some(1),
            Vec::new(),
            Vec::new(),
            None,
            None,
        )
    };

    let calls = std::cell::Cell::new(0);
    let mut side_effects = CookSideEffects::for_test(
        |_, _, run_id| {
            calls.set(calls.get() + 1);
            if calls.get() == 1 {
                Err(setup_failure())
            } else {
                Ok(promotion(run_id))
            }
        },
        |_, _, _| unreachable!("no recovery"),
        |_, _, _, _| Ok(Value::Null),
    );
    let mut retries = Vec::new();
    let promoted = super::promote_with_gate_setup_retries(
        &mut side_effects,
        &lifecycle_store,
        &options,
        "gate-setup-retry-run",
        |retry, _, error| retries.push((retry, error.message.clone())),
    )
    .expect("second promotion succeeds");
    assert_eq!(
        promoted.source.run_id.as_deref(),
        Some("gate-setup-retry-run")
    );
    assert_eq!(calls.get(), 2);
    assert_eq!(retries.len(), 1);
    assert!(retries[0].1.contains("promotion.gate_setup"));

    let calls = std::cell::Cell::new(0);
    let mut always_failing = CookSideEffects::for_test(
        |_, _, _| {
            calls.set(calls.get() + 1);
            Err(setup_failure())
        },
        |_, _, _| unreachable!("no recovery"),
        |_, _, _, _| Ok(Value::Null),
    );
    let error = super::promote_with_gate_setup_retries(
        &mut always_failing,
        &lifecycle_store,
        &options,
        "gate-setup-retry-run",
        |_, _, _| {},
    )
    .expect_err("budget exhausted");
    assert_eq!(error.details["step_id"], "promotion.gate_setup");
    assert_eq!(calls.get(), 1 + super::GATE_SETUP_PROMOTION_RETRIES);

    let calls = std::cell::Cell::new(0);
    let mut rejected = CookSideEffects::for_test(
        |_, _, _| {
            calls.set(calls.get() + 1);
            Err(homeboy_core::Error::validation_invalid_argument(
                "patch",
                "candidate patch does not apply",
                None,
                None,
            ))
        },
        |_, _, _| unreachable!("no recovery"),
        |_, _, _, _| Ok(Value::Null),
    );
    super::promote_with_gate_setup_retries(
        &mut rejected,
        &lifecycle_store,
        &options,
        "gate-setup-retry-run",
        |_, _, _| panic!("a candidate rejection is not retried"),
    )
    .expect_err("rejection is final");
    assert_eq!(calls.get(), 1);
}

/// #16121: a gate setup failure caused by deterministic configuration (a Lab
/// gate rejected in preflight for a missing runner `secret_env` ref) cannot
/// change between attempts, so promotion is not retried.
#[test]
fn deterministic_gate_setup_configuration_failures_are_not_retried() {
    let context = homeboy_core::test_support::HermeticTestContext::new();
    let lifecycle_store = AgentTaskLifecycleStore::new(context.path_roots());
    let options = compile_options("gate-setup-config");
    let calls = std::cell::Cell::new(0);
    let mut misconfigured = CookSideEffects::for_test(
        |_, _, _| {
            calls.set(calls.get() + 1);
            let mut error = homeboy_core::Error::dependency_step_failed(
                "promotion.gate_setup",
                "destination_gate_workspace".to_string(),
                None,
                Vec::new(),
                Vec::new(),
                None,
                Some(serde_json::json!({
                    "classification": "destination_gate_toolchain",
                    "code": "validation.invalid_argument",
                    "message": "Lab gate transport did not produce verified passing evidence: missing runner secret env ref for WP_CODEBOX_DB_HOST",
                    "retry_action": "fix_configuration",
                })),
            );
            error.retryable = Some(false);
            Err(error)
        },
        |_, _, _| unreachable!("no recovery"),
        |_, _, _, _| Ok(Value::Null),
    );
    let error = super::promote_with_gate_setup_retries(
        &mut misconfigured,
        &lifecycle_store,
        &options,
        "gate-setup-config-run",
        |_, _, _| panic!("deterministic configuration failures are not retried"),
    )
    .expect_err("configuration failure is final");
    assert_eq!(calls.get(), 1);
    assert_eq!(error.details["cause"]["retry_action"], "fix_configuration");
}

/// #15364: detached Lab dispatch returns before the runner daemon accepts the
/// handoff; the acceptance receipt is written minutes later by staging. The
/// controller waits for it instead of failing on the first read, and a
/// terminal attempt without a receipt stops the wait early.
#[test]
fn dispatch_acceptance_receipt_is_awaited_and_terminal_attempts_stop_the_wait() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let store = test_lifecycle_store();
        let options = compile_options("receipt-wait");
        let run_id = "receipt-wait-retry";
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(run_id)).unwrap();
        let operation_key = format!("dispatch:{run_id}");
        let intent = serde_json::json!({
            "schema": "homeboy/cook-dispatch-intent/v1",
            "run_id": run_id,
            "operation_key": operation_key,
        });
        agent_task_lifecycle::claim_operation_with_intent_in_store(
            &store,
            run_id,
            &operation_key,
            std::time::Duration::from_secs(60),
            &intent,
        )
        .unwrap();
        assert!(agent_task_lifecycle::dispatch_acceptance_receipt_in_store(
            &store,
            run_id,
            &operation_key
        )
        .unwrap()
        .is_none());

        let accept = std::thread::spawn({
            let run_id = run_id.to_string();
            move || {
                std::thread::sleep(std::time::Duration::from_millis(100));
                agent_task_lifecycle::record_detached_lab_run(
                    agent_task_lifecycle::DetachedLabRunRecord {
                        run_id: &run_id,
                        runner_id: "fixture-lab",
                        runner_job_id: "late-accepted-job",
                        remote_workspace: "/runner/workspace",
                        remote_command: &["homeboy".to_string()],
                    },
                )
                .unwrap();
            }
        });
        let receipt = super::await_dispatch_acceptance_receipt(
            &store,
            run_id,
            &operation_key,
            std::time::Duration::from_secs(30),
        )
        .unwrap()
        .expect("late receipt is observed");
        accept.join().unwrap();
        assert_eq!(receipt["receipt"]["runner_job_id"], "late-accepted-job");

        // A terminal attempt with no receipt returns promptly.
        let rejected = "receipt-wait-rejected";
        agent_task_lifecycle::submit_plan(&options.identity.initial_plan, Some(rejected)).unwrap();
        store
            .mutate_record(rejected, |record| {
                record.set_state_for_test(agent_task_lifecycle::AgentTaskRunState::Failed);
                true
            })
            .unwrap();
        let started = std::time::Instant::now();
        assert!(super::await_dispatch_acceptance_receipt(
            &store,
            rejected,
            &format!("dispatch:{rejected}"),
            std::time::Duration::from_secs(30),
        )
        .unwrap()
        .is_none());
        assert!(started.elapsed() < std::time::Duration::from_secs(5));
    });
}

/// A Cook continuation that already holds a promoted candidate must not
/// fast-forward its destination to the original base pin: the candidate was
/// verified on the destination's recorded HEAD, and moving it made
/// finalization refuse "candidate changed after promotion" (roadie#5 on
/// extrachill.com). Without a tracked candidate the behind-destination path
/// is unchanged and still reports the ancestry error for non-native targets.
#[test]
fn tracked_candidate_destination_is_not_converged_to_a_newer_pinned_base() {
    homeboy_core::test_support::with_isolated_home(|_| {
        let remote = tempfile::tempdir().expect("bare origin");
        let workspace = tempfile::tempdir().expect("workspace");
        let git = |cwd: &std::path::Path, args: &[&str]| {
            let output = Command::new("git")
                .args(["-c", "user.email=t@example.com", "-c", "user.name=T"])
                .args(args)
                .current_dir(cwd)
                .output()
                .expect("run git");
            assert!(
                output.status.success(),
                "git {:?} failed: {}",
                args,
                String::from_utf8_lossy(&output.stderr)
            );
            String::from_utf8_lossy(&output.stdout).trim().to_string()
        };
        git(remote.path(), &["init", "--bare", "-b", "main"]);
        git(workspace.path(), &["init", "-b", "main"]);
        git(
            workspace.path(),
            &["remote", "add", "origin", remote.path().to_str().unwrap()],
        );
        std::fs::write(workspace.path().join("base.txt"), "base\n").unwrap();
        git(workspace.path(), &["add", "."]);
        git(workspace.path(), &["commit", "-q", "-m", "base"]);
        git(workspace.path(), &["push", "-q", "-u", "origin", "main"]);
        let promoted_head = git(workspace.path(), &["rev-parse", "HEAD"]);
        let destination = tempfile::tempdir().expect("destination");
        git(
            destination.path(),
            &["clone", "-q", remote.path().to_str().unwrap(), "."],
        );
        // The base moves on after the candidate was promoted.
        std::fs::write(workspace.path().join("newer.txt"), "newer\n").unwrap();
        git(workspace.path(), &["add", "."]);
        git(workspace.path(), &["commit", "-q", "-m", "newer base"]);
        git(workspace.path(), &["push", "-q"]);
        let pinned_base = git(workspace.path(), &["rev-parse", "HEAD"]);
        git(destination.path(), &["fetch", "-q", "origin"]);

        let mut options = compile_options("tracked-candidate-base");
        options.workspace.to_worktree = destination.path().display().to_string();
        options.workspace.task_base_sha = Some(pinned_base.clone());

        let tracked = super::preflight_cook_workspace_base_ancestry_with_provider(
            destination.path(),
            &options,
            false,
            true,
        )
        .expect("a tracked candidate's verified destination is accepted");
        assert!(tracked.is_none());
        assert_eq!(
            git(destination.path(), &["rev-parse", "HEAD"]),
            promoted_head,
            "the destination stays on the HEAD its candidate was verified on"
        );

        let untracked = super::preflight_cook_workspace_base_ancestry_with_provider(
            destination.path(),
            &options,
            false,
            false,
        );
        assert!(
            matches!(
                untracked,
                Ok(Some(CookWorkspaceBaseValidation::Snapshot(_)))
            ),
            "an unregistered provider checkout uses a snapshot, never a managed reset"
        );
    });
}

/// A linked task worktree registered as the native destination `handle`,
/// owned by `owner_run_id`, with one committed tracked file.
fn prior_candidate_destination(
    home: &std::path::Path,
    handle: &str,
    owner_run_id: &str,
) -> (tempfile::TempDir, std::path::PathBuf) {
    let primary = tempfile::tempdir_in(home).expect("primary repository");
    let target = home.join("recook-destination");
    let git = |cwd: &std::path::Path, args: &[&str]| {
        let output = Command::new("git")
            .args(args)
            .current_dir(cwd)
            .output()
            .expect("run git");
        assert!(output.status.success(), "git {:?} failed", args);
    };
    git(primary.path(), &["init", "--initial-branch=main"]);
    git(
        primary.path(),
        &["config", "user.email", "agent@example.test"],
    );
    git(primary.path(), &["config", "user.name", "Agent"]);
    std::fs::write(primary.path().join("tracked.txt"), "base\n").expect("write base");
    git(primary.path(), &["add", "tracked.txt"]);
    git(primary.path(), &["commit", "-m", "base"]);
    git(
        primary.path(),
        &[
            "worktree",
            "add",
            "-b",
            "fix/issue-15775",
            target.to_str().expect("target path"),
        ],
    );
    git(
        primary.path(),
        &[
            "remote",
            "add",
            "origin",
            primary.path().to_str().expect("UTF-8 primary path"),
        ],
    );
    homeboy_core::worktree::record_active_for_run_at_for_test(handle, &target, owner_run_id);
    let target = std::fs::canonicalize(&target).expect("canonical target");
    (primary, target)
}

/// Materialize a prior Cook attempt and terminalize it as `state`.
fn materialize_prior_cook_attempt(cook_id: &str, state: AgentTaskRunState) -> String {
    let prior = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
    persist_initial_recipe(&prior).expect("persist prior Cook recipe");
    super::super::materialize_initial_cook_attempt(&prior).expect("materialize prior Cook");
    let run_id = prior.identity.initial_run_id.clone();
    AgentTaskLifecycleStore::from_current_environment()
        .expect("lifecycle store")
        .mutate_record(&run_id, |record| {
            record.set_state_for_test(state);
            true
        })
        .expect("terminalize prior Cook attempt");
    run_id
}

fn recook_options(cook_id: &str, handle: &str, target: &std::path::Path) -> CookRequest {
    let mut options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
    options.workspace.to_worktree = handle.to_string();
    options.workspace.source_worktree_path = Some(target.to_path_buf());
    options.identity.initial_plan.tasks[0].workspace.root = Some(target.display().to_string());
    options
}

fn leave_prior_candidate(target: &std::path::Path) {
    std::fs::write(target.join("tracked.txt"), "prior attempt edit\n").expect("edit tracked");
    std::fs::create_dir_all(target.join("tests")).expect("create untracked dir");
    std::fs::write(target.join("tests/runtime-smoke.php"), "<?php // prior\n")
        .expect("write untracked");
}

fn porcelain(target: &std::path::Path) -> String {
    let output = Command::new("git")
        .args(["status", "--porcelain=v1", "--untracked-files=all"])
        .current_dir(target)
        .output()
        .expect("git status");
    String::from_utf8_lossy(&output.stdout).to_string()
}

#[test]
fn recook_preserves_prior_failed_candidate_and_starts_from_clean_base() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let handle = "fixture@fix-issue-15775-fixture";
        let prior_run =
            materialize_prior_cook_attempt("cook-15775-prior", AgentTaskRunState::Failed);
        let (_primary, target) = prior_candidate_destination(home.path(), handle, &prior_run);
        leave_prior_candidate(&target);
        let head_before = git_output(&target, &["rev-parse", "HEAD"]).expect("HEAD");

        let options = recook_options("cook-15775-recook", handle, &target);
        persist_initial_recipe(&options).expect("persist re-cook recipe");
        super::super::materialize_initial_cook_attempt(&options).expect("materialize re-cook");
        let lifecycle_store =
            AgentTaskLifecycleStore::from_current_environment().expect("lifecycle store");
        let evidence = super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
            &lifecycle_store,
            &options,
        )
        .expect("preserve prior candidate")
        .expect("prior failed candidate is preserved");

        // The destination is clean at its unchanged base.
        assert_eq!(porcelain(&target), "");
        assert_eq!(
            git_output(&target, &["rev-parse", "HEAD"]).expect("HEAD"),
            head_before
        );
        assert_eq!(evidence["action"], "preserved_and_reset");
        assert_eq!(evidence["prior_run_id"], prior_run);
        assert_eq!(evidence["prior_run_state"], "failed");
        assert_eq!(evidence["changed_path_count"], 2);
        assert_eq!(
            evidence["changed_paths"],
            serde_json::json!(["tracked.txt", "tests/runtime-smoke.php"])
        );

        // The candidate is reachable from a durable ref and contains both the
        // tracked edit and the untracked file.
        let reference = evidence["ref"].as_str().expect("ref").to_string();
        assert!(reference.starts_with(&format!("refs/homeboy/preserved-candidates/{prior_run}/")));
        assert_eq!(
            git_output(&target, &["rev-parse", &reference]).expect("resolve ref"),
            evidence["commit"].as_str().expect("commit")
        );
        assert_eq!(
            git_output(&target, &["show", &format!("{reference}:tracked.txt")])
                .expect("show tracked"),
            "prior attempt edit"
        );
        assert_eq!(
            git_output(
                &target,
                &["show", &format!("{reference}:tests/runtime-smoke.php")]
            )
            .expect("show untracked"),
            "<?php // prior"
        );

        // The durable run evidence carries the same record.
        let record = lifecycle_store
            .read_record(&options.identity.initial_run_id)
            .expect("re-cook record");
        assert_eq!(
            record.metadata["cook_prior_attempt_candidate_preservation"],
            evidence
        );

        let prior = lifecycle_store
            .read_record(&prior_run)
            .expect("prior record");
        assert_eq!(
            prior.metadata["cook_prior_attempt_candidate_preservation"]["preserved_by_run_id"],
            options.identity.initial_run_id
        );

        // The recorded recovery command restores the prior candidate.
        let recovery = evidence["recovery_command"].as_str().expect("recovery");
        let restored = Command::new("sh")
            .args(["-c", recovery])
            .output()
            .expect("run recovery command");
        assert!(
            restored.status.success(),
            "{}",
            String::from_utf8_lossy(&restored.stderr)
        );
        assert_eq!(
            std::fs::read_to_string(target.join("tracked.txt")).expect("restored tracked"),
            "prior attempt edit\n"
        );
        assert!(target.join("tests/runtime-smoke.php").is_file());
    });
}

#[test]
fn recook_preservation_leaves_unattributed_dirt_for_existing_admission() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let handle = "fixture@fix-issue-15775-fixture";
        let lifecycle_store =
            AgentTaskLifecycleStore::from_current_environment().expect("lifecycle store");

        // Owner without a durable lifecycle record: dirt is not attributable.
        let (_primary, target) =
            prior_candidate_destination(home.path(), handle, "unknown-owner-run");
        leave_prior_candidate(&target);
        let dirty = porcelain(&target);
        let options = recook_options("cook-15775-unknown", handle, &target);
        assert_eq!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &options,
            )
            .expect("classify unknown owner"),
            None
        );
        assert_eq!(porcelain(&target), dirty);

        // A succeeded owner's leftovers are not a failed candidate.
        let succeeded =
            materialize_prior_cook_attempt("cook-15775-succeeded", AgentTaskRunState::Succeeded);
        homeboy_core::worktree::record_active_for_run_at_for_test(handle, &target, &succeeded);
        assert_eq!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &options,
            )
            .expect("classify succeeded owner"),
            None
        );

        // This Cook's own candidate stays with its continuation paths.
        let failed = materialize_prior_cook_attempt("cook-15775-own", AgentTaskRunState::Failed);
        homeboy_core::worktree::record_active_for_run_at_for_test(handle, &target, &failed);
        let mut own = recook_options("cook-15775-own", handle, &target);
        own.identity.initial_run_id = failed.clone();
        assert_eq!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &own,
            )
            .expect("classify own attempt"),
            None
        );

        // Explicit CWDs are caller-owned and never mutated.
        let mut explicit = recook_options("cook-15775-explicit", handle, &target);
        explicit.identity.initial_plan.tasks[0].metadata["worktree_provision"] =
            serde_json::json!({ "kind": "explicit_cwd" });
        assert_eq!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &explicit,
            )
            .expect("classify explicit CWD"),
            None
        );
        assert_eq!(porcelain(&target), dirty);
    });
}

/// A second Cook for the same issue derives the destination a still-driving
/// Cook provisioned. The provisioning attempt being terminal says nothing about
/// its Cook: the driver can be applying a later attempt's candidate there and
/// gating it. The second Cook is refused by name, and that candidate is never
/// preserved-and-reset out from under its driver.
#[test]
fn a_destination_whose_cook_is_still_driving_refuses_another_cook() {
    use fs4::fs_std::FileExt;
    homeboy_core::test_support::with_isolated_home(|home| {
        let handle = "fixture@fix-issue-15884-fixture";
        let prior_cook = "cook-15884-driving";
        let prior_run = materialize_prior_cook_attempt(prior_cook, AgentTaskRunState::Failed);
        let (_primary, target) = prior_candidate_destination(home.path(), handle, &prior_run);
        leave_prior_candidate(&target);
        let dirty = porcelain(&target);
        let options = recook_options("cook-15884-second", handle, &target);
        let lifecycle_store =
            AgentTaskLifecycleStore::from_current_environment().expect("lifecycle store");

        let lock_path = homeboy_core::paths::homeboy_data()
            .expect("data root")
            .join("agent-task-cooks")
            .join(prior_cook)
            .join("driver.lock");
        let driver = std::fs::OpenOptions::new()
            .create(true)
            .truncate(false)
            .read(true)
            .write(true)
            .open(&lock_path)
            .expect("driver lock");
        assert!(driver.try_lock_exclusive().expect("hold driver lock"));

        let error = super::super::cook_prior_candidate::require_destination_free_of_live_cook(
            &lifecycle_store,
            &options,
        )
        .expect_err("a live owner Cook keeps its destination");
        assert_eq!(error.details["destination_owner"]["cook_id"], prior_cook);
        assert_eq!(error.details["destination_owner"]["run_id"], prior_run);
        assert_eq!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &options,
            )
            .expect("classify live owner"),
            None
        );
        assert_eq!(porcelain(&target), dirty);

        // Once the owner's driver exits, its failed candidate is the #15775
        // re-cook case again.
        drop(driver);
        super::super::cook_prior_candidate::require_destination_free_of_live_cook(
            &lifecycle_store,
            &options,
        )
        .expect("a stopped owner Cook no longer holds the destination");
        assert!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &options,
            )
            .expect("preserve stopped owner's candidate")
            .is_some()
        );
        assert_eq!(porcelain(&target), "");
    });
}

#[test]
fn cook_takes_over_a_nonterminal_destination_after_driver_death() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let handle = "fixture@fix-issue-16323-fixture";
        let prior_cook = "cook-16323-dead";
        let prior_run = materialize_prior_cook_attempt(prior_cook, AgentTaskRunState::Running);
        let (_primary, target) = prior_candidate_destination(home.path(), handle, &prior_run);
        leave_prior_candidate(&target);
        let options = recook_options("cook-16323-takeover", handle, &target);
        let lifecycle_store = AgentTaskLifecycleStore::from_current_environment().unwrap();
        // A stale PID is diagnostic only: the unlocked OS lock is the proof.
        let lock_path = homeboy_core::paths::homeboy_data()
            .unwrap()
            .join("agent-task-cooks")
            .join(prior_cook)
            .join("driver.lock");
        std::fs::write(lock_path, "99999999").unwrap();
        super::super::cook_prior_candidate::require_destination_free_of_live_cook(
            &lifecycle_store,
            &options,
        )
        .unwrap();
        let evidence = super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
            &lifecycle_store,
            &options,
        )
        .unwrap()
        .unwrap();
        assert_eq!(evidence["prior_run_id"], prior_run);
        assert_eq!(porcelain(&target), "");
        assert!(evidence["recovery_command"]
            .as_str()
            .unwrap()
            .contains("cherry-pick --no-commit"));
    });
}

#[test]
fn recook_preservation_is_a_noop_for_a_clean_prior_destination() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let handle = "fixture@fix-issue-15775-fixture";
        let prior_run =
            materialize_prior_cook_attempt("cook-15775-clean-prior", AgentTaskRunState::Failed);
        let (_primary, target) = prior_candidate_destination(home.path(), handle, &prior_run);
        let options = recook_options("cook-15775-clean", handle, &target);
        let lifecycle_store =
            AgentTaskLifecycleStore::from_current_environment().expect("lifecycle store");
        assert_eq!(
            super::super::cook_prior_candidate::preserve_prior_attempt_candidate(
                &lifecycle_store,
                &options,
            )
            .expect("classify clean destination"),
            None
        );
        let refs = git_output(
            &target,
            &["for-each-ref", "refs/homeboy/preserved-candidates"],
        )
        .expect("list preserved refs");
        assert_eq!(refs, "");
    });
}

#[test]
fn run_cook_preserves_prior_failed_candidate_before_detached_dispatch() {
    homeboy_core::test_support::with_isolated_home(|home| {
        let handle = "fixture@fix-issue-15775-fixture";
        let prior_run =
            materialize_prior_cook_attempt("cook-15775-spine-prior", AgentTaskRunState::Failed);
        let (_primary, target) = prior_candidate_destination(home.path(), handle, &prior_run);
        leave_prior_candidate(&target);

        let dispatches = Arc::new(AtomicUsize::new(0));
        let mut options = batch_cook_options(
            "cook-15775-spine",
            Arc::new(RecordingDetachedAttemptDispatcher {
                dispatches: dispatches.clone(),
            }),
        );
        options.workspace.to_worktree = handle.to_string();
        options.workspace.source_worktree_path = Some(target.clone());
        options.identity.initial_plan.tasks[0].workspace.root = Some(target.display().to_string());
        options.ai_disclosure.ai_model = Some("openai/gpt-5.6-terra".to_string());
        let run_id = options.identity.initial_run_id.clone();

        let result = run_cook(CookContext::new(options, Arc::new(UnusedExecutor)));
        // The destination is clean before any provider or Lab snapshot saw it.
        assert_eq!(porcelain(&target), "");
        // The terminal prior run durably records where its candidate went;
        // the detached handoff re-projects the new run's record.
        let prior = AgentTaskLifecycleStore::from_current_environment()
            .expect("lifecycle store")
            .read_record(&prior_run)
            .expect("prior record");
        let evidence = &prior.metadata["cook_prior_attempt_candidate_preservation"];
        assert_eq!(evidence["prior_run_id"], prior_run, "result: {result:?}");
        assert_eq!(evidence["preserved_by_run_id"], run_id);
        assert_eq!(evidence["action"], "preserved_and_reset");
        let reference = evidence["ref"].as_str().expect("ref");
        assert_eq!(
            git_output(&target, &["show", &format!("{reference}:tracked.txt")])
                .expect("show preserved tracked"),
            "prior attempt edit"
        );
        assert_eq!(dispatches.load(Ordering::SeqCst), 1, "result: {result:?}");
    });
}

fn commit_message_finalization_options(
    commit_message: &str,
) -> crate::agent_task_finalization::AgentTaskPrFinalizationOptions {
    finalization_options_for_task(commit_message, None, Vec::new())
}

fn finalization_options_for_task(
    commit_message: &str,
    origin: Option<&str>,
    source_refs: Vec<String>,
) -> crate::agent_task_finalization::AgentTaskPrFinalizationOptions {
    let recipe_context = homeboy_core::test_support::HermeticTestContext::new();
    let lifecycle_context = homeboy_core::test_support::HermeticTestContext::new();
    let recipe_store = CookRecipeStore::new(recipe_context.path_roots());
    let lifecycle_store = AgentTaskLifecycleStore::new(lifecycle_context.path_roots());
    let cook_id = "commit-subject-cook";
    let run_id = "commit-subject-run";
    let target = tempfile::tempdir().expect("fixture target");
    let mut options = batch_cook_options(cook_id, Arc::new(AcceptedDetachedAttemptDispatcher));
    options.identity.initial_run_id = run_id.to_string();
    options.identity.initial_plan.tasks[0].executor.model =
        Some("commit-subject-model".to_string());
    // Prompt-only Cook: the title comes from the agent form.
    options.finalization.title.clear();
    options.finalization.commit_message = commit_message.to_string();
    options.workspace.source_refs = source_refs;
    if let Some(origin) = origin {
        git_output(target.path(), &["init", "-q"]).expect("init destination checkout");
        git_output(target.path(), &["remote", "add", "origin", origin]).expect("add origin");
    }
    recipe_store
        .persist_initial_recipe(&options)
        .expect("persist the recipe");
    lifecycle_store
        .submit_plan_with_runtime_admission(&options.identity.initial_plan, run_id, |_| {
            Ok(serde_json::json!({}))
        })
        .expect("seed the run record");
    lifecycle_store
        .record_cook_attempt(cook_id, 1, run_id)
        .expect("record the cook attempt");
    lifecycle_store
        .record_run_aggregate(
            run_id,
            &options.identity.initial_plan,
            &review_form_aggregate(&options.identity.initial_plan),
        )
        .expect("record the review-form aggregate");
    let promotion = promotion_with_existing_path(run_id, target.path());
    cook_finalization_options_with_stores(
        &recipe_store,
        &lifecycle_store,
        &options,
        run_id,
        &promotion,
        Vec::new(),
    )
    .expect("build finalization options")
}

#[test]
fn cook_commit_subject_is_the_validated_form_title_without_an_explicit_message() {
    // #16052: a Cook PR has one commit and GitHub squash-merges it under that
    // commit's subject, so the commit must carry the specific PR title rather
    // than a generic `fix: cook <repo>`.
    let options = commit_message_finalization_options("");
    assert_eq!(options.commit_message, test_review_form().pr_title);
    assert_eq!(options.title, test_review_form().pr_title);
}

#[test]
fn cook_commit_subject_keeps_an_explicit_commit_message() {
    let options = commit_message_finalization_options("chore: operator-chosen subject");
    assert_eq!(options.commit_message, "chore: operator-chosen subject");
    assert_eq!(options.title, test_review_form().pr_title);
}

#[test]
fn cook_commit_subject_falls_back_only_when_no_title_exists() {
    use super::super::cook_promotion::cook_commit_message;
    assert_eq!(
        cook_commit_message("", "  ", Some("blocks-engine")),
        "fix: cook blocks-engine"
    );
    assert_eq!(cook_commit_message("", "", None), "fix: cook agent task");
    assert_eq!(
        cook_commit_message("", "Guard the reload path", Some("blocks-engine")),
        "Guard the reload path"
    );
}

fn task_issue_relationship_pr_body(origin: &str, task_url: &str) -> String {
    let mut options = finalization_options_for_task("", Some(origin), vec![task_url.to_string()]);
    crate::agent_task_review_dossier::enrich_dossier(
        &mut options.review_dossier,
        &options.evidence.artifact_refs,
        &[],
    );
    options
        .review_dossier
        .validate(&options.review_profile)
        .expect("enriched Cook dossier stays valid");
    crate::agent_task_review_dossier::render_review_dossier(
        &options.review_dossier,
        &options.review_profile,
    )
}

#[test]
fn cook_pr_body_closes_same_repo_task_issue_relationship() {
    let body = task_issue_relationship_pr_body(
        "git@github.com:Fixture-Owner/fixture-repo.git",
        "https://github.com/fixture-owner/Fixture-Repo/issues/16247",
    );
    assert!(body.contains("Closes #16247"), "{body}");
}

#[test]
fn cook_pr_body_relates_cross_repo_task_issue_relationship() {
    let body = task_issue_relationship_pr_body(
        "https://github.com/Fixture-Owner/fixture-repo.git",
        "https://github.com/Fixture-Owner/other-repo/issues/42",
    );
    assert!(
        body.contains("Relates to Fixture-Owner/other-repo#42"),
        "{body}"
    );
    assert!(!body.contains("Closes"), "{body}");
}

#[test]
fn cook_pr_body_never_closes_pull_request_or_external_task_issue_relationship() {
    for task_url in [
        "https://github.com/Fixture-Owner/fixture-repo/pull/16000",
        "https://linear.app/extra-chill/issue/HB-12",
    ] {
        let body = task_issue_relationship_pr_body(
            "https://github.com/Fixture-Owner/fixture-repo.git",
            task_url,
        );
        assert!(!body.contains("Closes"), "{task_url}: {body}");
        assert!(body.contains("Relates to"), "{task_url}: {body}");
    }
}
